(window.STORIES=window.STORIES||[]).push(...[{"n": 248, "l": "الجزء 222 | صاحب الرغيف", "u": "https://www.facebook.com/groups/710210019782034/permalink/837723783697323/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائتين_واثنين_وعشرين\n#أحداث_السنة_العاشرة_من_الهجرة\n#صاحب_الرغيف\nاتكلمنا المرة إللي فاتت عن أبي موسى الأشعري رضي الله عنه وعرفنا عنه معلومات عامة، \nهنشوف النهاردة إن شاء الله قصة بيحكيها أبو موسى الأشعري لأبنائه لما جاءه وقت الاحتضار، \nقال أبو موسى الأشعري رضي الله عنه:\n\"يَا بَنِي اذْكُرُوا صَاحِبَ الرَّغِيفِ!\"\nفسألوه مين هو صاحب الرغيف ده، قال لهم:\n\"كَانَ رَجُلٌ يَتَعَبَّدُ فِي صَوْمَعَةٍ سَبْعِينَ سَنَةً، لَا يَنْزِلُ إِلَّا فِي يَوْمِ أَحَدٍ...\"\nيعني كان في رجل من بني إسرائيل منعزل للعبادة في صومعة، وقعد يعبد ربنا في العزلة بتاعته دي سبعين سنة،\nومكنش بينزل من صومعته دي غير كل يوم أحد وفي رواية تانية إنه كان بينزل يوم واحد كل فترة يجيب إللي محتاجه من المدينة ويرجع لصومعته،\nقَالَ: \n\"فَنَزَلَ فِي يَوْمِ أَحَدٍ، فشَبَّ الشَّيْطَانُ فِي عَيْنِهِ امْرَأَة، فَكَانَ مَعَهَا سَبْعَةَ أَيَّامٍ أَوْ سَبْعَ لَيَالٍ\"\nيعني مرة نزل في اليوم إللي بينزل فيه كالعادة فشاف امرأة جميلة زينها له الشيطان، فأعجب بيها وعاشرها في الحرام سبع أيام أو سبع ليال\nوزي ما رسول الله ﷺ قال:\n\" اتقوا الدنيا، واتقوا النساءَ؛ فإنَّ أَوَّلَ فتنةِ بني إسرائيلَ كانت في النساءِ\"\nأهه واحد قعد يعبد ربنا سبعين سنة وفتنته كانت في امرأة،\nفالرجل أضعف ما يكون عند النساء، وخصوصا إذا كانت فاجرة وتُحسن التصنع والتكسر وتُميل الرجل إليها،\nولو المرأة دي كانت عفيفة مكنتش رضيت أصلا إنها تزني مع رجل كبير في السن سبع ليال\nوالموضوع مكنش مرة وخلاص، ده قعد معاها في الزنا سبع ليال، وطبعا دي فترة طويلة بالنسبة لعابد،\nوده يعرفنا إن الإنسان إذا وقع في الشهوة ميقدرش يتخلص منها بسهولة\nالمهم بعد السبع ليال دول:\n\"كُشِفَ عَنِ الرَّجُلِ غِطَاؤُهُ فَخَرَجَ تَائِبًا، فَكَانَ كُلَّمَا خَطَا خُطْوَةً صَلَّى وَسَجَدَ...\"\nيعني الغشاوة إللي كانت على عينه من الشهوة والمعصية رُفعت والرجل فاق لنفسه وشاف المصيبة إللي هو وقع فيها،\nوهو ده حال الشيطان مع الإنسان بصفة عامة يقعد يزين له المعصية ويدعوه لها لحد ما يقع فيها،\nوبعدين بقى يتركه للندم والحسرة وممكن يؤدي به الحال في النهاية للكفر زي ما حصل مع برصيصا العابد إللي حكينا قصته قبل كده،\nفالإنسان مش بيبقى شايف الندم والحسرة إللي هيقع فيهم قبل المعصية، بيبقى شايف لذة المعصية فقط وكأن على عينه غشاوة،\nأول ما يقع في المعصية وتزول الغشاوة يشوف الأمور على حقيقتها زي ما حصل مع العابد إللي بنتكلم عنه دلوقتي\nلما الرجل شاف الكبيرة إللي وقع فيها خرج من عند المرأة تائب لله،\nوكان كل خطوة يمشيها يسجد لله سجدة،\nأكمل أبو موسى القصة وقَالَ: \n\"فَآوَاهُ اللَّيْلُ إِلَى مَكَانٍ عَلَيْهِ اثْنَا عَشَرَ مِسْكِينًا، فَأَدْرَكَ الْإِعْيَاءَ، فَرَمَى بِنَفْسِهِ بَيْنَ رَجُلَيْنِ مِنْهُمْ...\"\nيعني الرجل ده استمر على حاله ده لحد ما جاء الليل ووصل لمكان فيه اثنا عشر مسكين وكان تعب جدا فرمى نفسه وقعد بين رجلين من المساكين دول،\n\"وَكَانَ ثَمَّ رَاهِبٌ يَبْعَثُ إِلَيْهِمْ كُلَّ لَيْلَةٍ بِأَرْغِفَةٍ فَيُعْطِي كُلَّ إِنْسَانٍ رَغِيفًا....\"\nيعني كان في راهب بيتصدق على المساكين دول كل ليلة برغيف لكل واحد،\nفكان بيأتي باثنا عشر رغيفا،\n\"فَجَاءَ صَاحِبُ الرَّغِيفِ فَأَعْطَى كُلَّ إِنْسَانٍ رَغِيفًا، وَمَرَّ عَلَى ذَلِكَ الَّذِي خَرَجَ تَائِبًا، فَظَنَّ أَنَّهُ مِسْكِينٌ فَأَعْطَاهُ رَغِيفًا...\"\nيعني الراهب جاء على عادته عشان يعطي المساكين الأرغفة بتاعتهم، فأعطى لكل واحد منهم رغيف،\nوكان الرجل إللي خرج تائب قاعد وسطهم فالراهب ظن إنه مسكين من المساكين فأعطاه رغيف،\nفكده بقى عندنا عجز في رغيف، وفي واحد من المساكين لم يأخذ رغيف\nفَقَالَ الْمَتْرُوكُ لِصَاحِبِ الرَّغِيفِ: \n\"مَا لَكَ، لَمْ تُعْطِنِي رَغِيفِي، مَا كَانَ إليَّ عَنْهُ غِنًى\"\nيعني المسكين إللي كان متعود ياخد رغيف كل يوم مأخدش فقال للراهب، انت مدتنيش رغيفي بتاع النهاردة وأنا محتاجه ومقدرش استغنى عنه،\nفقال الراهب:\nتُرَانِي أُمْسِكُهُ عَنْكَ، سَلْ هَلْ أَعْطَيْتُ أَحَدًا مِنْكُمْ رَغِيفَيْنِ؟\nيعني بيقول له انت مفكرني همنع عنك الرغيف بتاعك، وسأل باقي المساكين إذا كان أعطى لواحد منهم رغيفين بالغلط،\n فقَالُوا: لَا! \nقَالَ: إِنِّي أَمْسِكُ عَنْكَ وَاللَّهِ لَا أُعْطِيكَ شَيْئًا اللَّيْلَةَ!\nيعني والله مانا مديك حاجة النهاردة خالص\nفالرجل التائب سمع الحوار، \nفَعَمَدَ التَّائِبُ إِلَى الرَّغِيفِ الَّذِي دَفَعَهُ إِلَيْهِ، فَدَفَعَهُ إِلَى الرَّجُلِ الَّذِي تُرِكَ فَأَصْبَحَ التَّائِبُ مَيِّتًا!\nيعني الرجل التائب ده أعطى المسكين الرغيف إللي الراهب كان أعطاه له بالخطأ، ونام الراهب ومات\nيقول أبو موسى الأشعري رضي الله عنه:\n\"فَوُزِنَتِ السَّبْعُونَ سَنَةً بِالسَّبْعِ اللَّيَالِي فَلَمْ تَزِنْ\"\nانتم عارفين إن يوم القيامة الأعمال هتتوزن صح\nيعني الأعمال الصالحة هتوضع في كفة والسيئات هتوضع في كفة، وإللي كفة حسناته هترجح هو إللي يدخل الجنة وإللي هترجح كفة سيئاته هيدخل النار،\nفالرجل التائب ده وُضعت له عبادة سبعين سنة في كفة ووضع في مقابلها السبع ليالي إللي قضاها في الزنا فرجحت السبع ليالي،\nقال أبو موسى:\n\"فَوُزِنَ الرَّغِيفُ بِالسَّبْعِ اللَّيَالِي،فَرَجَحَ الرَّغِيف\"\nيعني الرغيف إللي الرجل ده أعطاه للمسكين بقى في ميزان حسناته، \nفالحسنة دي لما وُضعت في الميزان مقابل السبع ليالي رجحت كفة الرغيف فغفر الله له ودخل الحنة،\nفَقَالَ أَبُو مُوسَى في النهاية: \"يَا بَنِيَّ اذْكُرُوا صَاحِبَ الرَّغِيفِ\"\nيعني خليكم فاكرين قصة صاحب الرغيف\n☆سؤال بقى،\nإيه الهدف إن أبو موسى الأشعري رضي الله عنه يذكر القصة دي بالذات عند موته\nشوفوا،\nرسول الله ﷺ بيقول:\n\"لا يموتنَّ أحدكم إلا وهو يحسنُ الظنَّ باللهِ عزَّ وجلَّ\"\nوربنا بيقول في الحديث القدسي:\n\"أنا عندَ ظنِّ عبدي بي إنْ ظنَّ خيرًا فله وإن ظنَّ شرًّا فلَه\"\nوالمعنى إن الإنسان لما تيجي لحظة موته لازم يحسن الظن بالله إن رحمته واسعة وإنه غافر للذنب،\nفلما يظن كده في ربنا ساعتها ربنا هيرحمه ويغفر له بحسب ظنه به،\nفأبو موسى الأشعري هنا في لحظات احتضاره بيهوّن على نفسه ويذكر أبناؤه برحمة الله وإن ربنا غفر للرجل إللي عاش سبع ليالي في الزنا بسبب رغيف خبز\nفعشان كده لو لما يكون حد بيحتضر بنقعد نذكره برحمة الله ونبعد عنه أي تخويف أو تذكير بعذاب الله عشان ميوصلش للقنوط واليأس من رحمة الله،\nالترهيب مع الترغيب يبقى لما يكون الإنسان عايش عادي، لكن وقت الموت مينفعش ترهيب خالص، لازم ترغيب فقط\n◇ملحوظة:\nحديث صاحب الرغيف حديث صحيح، لكن العلماء اختلفوا هل هو حديث مرفوع لرسول الله ﷺ ولّا موقوف على الصحابي أبي موسى الأشعري \nالحديث المرفوع باختصار وببساطة معناه إن الصحابي بيحكي عن شيء سمعه أو شافه من رسول الله ﷺ، ومن أنواعه إن الصحابي يحكي  من غير ما يقول:\n《قال رسول الله ﷺ 》\nوالحديث الموقوف هو الحديث إللي بيقف عند الصحابي، يعني سواء قوله أو فعله، وملوش دعوة برسول الله ﷺ،\nففي علماء قالوا إن حديث صاحب الرغيف مرفوع،\nيعني أبو موسى كان سمعه من رسول الله ﷺ وحكى القصة لأبنائه،\nلأن الأحداث دي من الغيب إللي مينفعش فيها اجتهاد بالرأي، ولازم فيها نص شرعي\nوفريق من العلماء قالوا إن الحديث ده موقوف، وأبو موسى رضي الله عنه عرف القصة من أهل الكتاب وحكاها عادي لأن رسول الله ﷺ قال:\n\"حَدِّثُوا عنْ بَنِي إسْرَائيل وَلا حَرجَ\"\nفالقصة من باب العبرة والعظة وليس فيها إثبات لحكم شرعي مثلا، وخصوصا إن عندنا في الشرع ما يؤكد معنى القصة وهي إن ربنا يغفر الذنب العظيم بسبب عمل صالح بسيط، زي المرأة البغي إللي سقت كلب\nقال رسول الله ﷺ:\n\"غُفِرَ لِامْرَأَةٍ مُومِسَةٍ مَرَّتْ بِكَلْبٍ عَلَى رَأْسِ رَكِيٍّ يَلْهَثُ، كَادَ يَقْتُلُهُ الْعَطَشُ، فَنَزَعَتْ خُفَّهَا، فَأَوْثَقَتْهُ بِخِمَارِهَا، فَنَزَعَتْ لَهُ مِنْ الْمَاءِ؛ فَغُفِرَ لَهَا بِذَلِكَ\"\nيعني ربنا غفر لامرأة بغي تتاجر بعرضها مقابل الماء لأنها شافت كلب بيطوف حول بئر وكان عطشان جدا لدرجة إنه كان هيموت من شدة العطش،\nفالمرأة خلعت الخف أو الحذاء إللي كانت لابساه وربطته في غطاء رأس كانت لابساه ونزلت الخف في البئر وملته مية ورفعته وسقت الكلب العطشان،\nفهي لما رحمت الكلب، ربنا رحمها وغفر لها، \nوالكلام مش معناه إن البغايا بقى يروحوا يسقوا الكلاب ويقولوا ربنا هيعفر لنا\nلأ، ده الموضوع أمر قلبي لا يعلمه إلا الله، ربنا لما شاف الرحمة إللي كانت في قلب البغي ناحية الكلب رحمها وهو واسع الرحمة سبحانه،\nفالشاهد من القصتين إن الإنسان لا يحتقر معروفا أبدا، \nويعمل الأعمال الصالحة مهما كانت بسيطة ولا تُذكر في نظره\nحتى رسول الله ﷺ قال:\n\" لا تحقرَنَّ من المعروفِ شيئًا، ولو أن تلقَى أخاك بوجهٍ طلِقٍ\"\nيعني محدش يستقل عمل صالح مهما كان بسيط ولو إن الواحد فينا لما يقابل الناس يكون وجهه ضاحك مستبشر مش يبقى كئيب وعابس\nوفي نفس الوقت طبعا الواحد لا يستهين أبدا بمعصية\nوانتم شوفتم إزاي سنين من الطاعة ضاعت قصاد سبع أيام من المعصية،\nومتنسوش إن إبليس بقى مخلد في النار بسبب معصية واحدة لله،\nوكذلك المرأة إللي دخلت النار بسبب قطة حبستها، فلا هي أطعمتها ولا تركتها تأكل من رزق الله\nفالواحد ممكن ربنا ينجيه بأهون شيء، يعني ممكن مثلا الشيء إللي نعمله بطريقة عفوية لله يكون أبرك من أعمال كثيرة الإنسان شايفها عظيمة وبيعتز بيها،\nفأعمال البر لا تُوزن بعددها فقط، لكن كمان بقوة الإخلاص\nمن القصص إللي حكاها رسول الله ﷺ للصحابة وفيها معنى الإخلاص ظاهر؛ قصة الرجل المتصدق،\nيقول رسول الله ﷺ:\n\"قالَ رَجُلٌ: لَأَتَصَدَّقَنَّ بصَدَقَةٍ، فَخَرَجَ بصَدَقَتِهِ، فَوَضَعَهَا في يَدِ سَارِقٍ....\"\nيعني كان في رجل عايز يتصدق بصدقة لله، فأخذ ماله وخرج يتصدق، فقابل رجل ميعرفوش فأعطى له الصدقة، وكان تصدق بالصدقة دي في الليل،\nوطبعا انتم عارفين زمان مكنش في أضواء فهو لم يميز الشخص إللي أعطى له الصدقة، هو شاف واحد عليه علامات الفقر فأعطى له المال ومشي،\nوكمان هو اختار التصدق في الليل عشان تكون الصدقة أقرب للإخلاص،\nوصدقة السر أفضل للعبد من إنه يتصدق أمام الناس، ربنا بيقول في سورة البقرة:\n\" إِن تُبْدُوا الصَّدَقَاتِ فَنِعِمَّا هِيَ ۖ وَإِن تُخْفُوهَا وَتُؤْتُوهَا الْفُقَرَاءَ فَهُوَ خَيْرٌ لَّكُمْ\"\nيعني لو أظهرتم الصدقة فده شيء كويس لأن فيه منفعة للفقير لأن كده الناس هتقلد المتصدق وتعطي الفقراء،\nلكن الأفضل لكم انتم إنكم تخفوا الصدقة دي عشان الإخلاص،\nفالرجل تصدق بالصدقة في السر، \nلكن إللي تصدق عليه ده طلع رجل سارق وهو مكنش يعرف إنه سارق\nفالناس تاني يوم قعدوا يتكلموا إن الليلة إللي فاتت تُصِدّق على سارق،\nفالرجل المتصدق عرف إن هو المقصود بالكلام فقال:\n\" اللَّهُمَّ لكَ الحَمْدُ على سارق، لَأَتَصَدَّقَنَّ بصَدَقَةٍ\"\nيعني هو كان عايز الصدقة تقع في يد واحد يستحقها، فلما محصلش إللي كان عايزه حمد الله على كل حال،\nولأنه عايز الصدقة تقع في يد واحد يستحقها قال أنا هتصدق بصدقة تانية.\n☆محدش يسألني الناس عرفوا منين إن تُصدق على سارق، ولّا الرجل نفسه عرف منين إنه المقصود بالكلام أصلا مش حد تاني عشان أنا نفسي معرفش\nفاحنا خلينا نركز في الهدف والعبرة من القصة ماشي\nالرجل خرج في الليل برده يتصدق بصدقة، فوقعت الصدقة في يَدَيْ زَانِيَةٍ، فأصْبَحُوا يَتَحَدَّثُونَ: تُصُدِّقَ اللَّيْلَةَ علَى زَانِيَةٍ، فَقالَ: اللَّهُمَّ لكَ الحَمْدُ، علَى زَانِيَةٍ.\nنفس الأحداث بس المرة دي الصدقة وقعت في يد امرأة زانية، فلما عرف حمد ربنا برده، وقال:\nلَأَتَصَدَّقَنَّ بصَدَقَةٍ...\nهو لسه مصمم برده عايز صدقته تقع في يد حد يستحقها، فخرج وتصدق فوقعت الصدقة في يَدَيْ غَنِيٍّ، فأصْبَحُوا يَتَحَدَّثُونَ: تُصُدِّقَ علَى غَنِيٍّ.\nفَقالَ: \nاللَّهُمَّ لكَ الحَمْدُ، علَى سَارِقٍ وعلَى زَانِيَةٍ وعلَى غَنِيٍّ\nهو كان عايز صدقته تقع في يد رجل فقير متعفف أو امرأة شريفة أو رجل أمين،\nلكن كل حاجة حصلت عكس تماما إللي كان عايزه\nفالرجل كأنه شاف إنه كل عمله ده مكنش له أي لازمة ولا له وزن،\nفلما نام شاف رؤيا وسمع بيكلمه وبيقول له:\n\" أَمَّا صَدَقَتُكَ علَى سَارِقٍ فَلَعَلَّهُ أَنْ يَسْتَعِفَّ عن سَرِقَتِهِ،\nوأَمَّا الزَّانِيَةُ فَلَعَلَّهَا أَنْ تَسْتَعِفَّ عن زِنَاهَا، \nوأَمَّا الغَنِيُّ فَلَعَلَّهُ يَعْتَبِرُ فيُنْفِقُ ممَّا أَعْطَاهُ اللَّهُ.\"\nيعني انت الصدقة بتاعتك ربنا تقبلها منك خلاص، والسارق ده يمكن يترك السرقة لأنه كان بيسرق لأنه محتاج للمال،\nفلما انت أعطيته المال ممكن ساعتها يترك السرقة، \nأما الزانية فهي كمان ممكن تكون محتاجة للمال فبتبيع عرضها من أجل المال.\n☆زي كده يا جماعة المرأة إللي كانت في قصة الثلاثة إللي دخلوا الغار وانسدت عليهم الصخرة،\nوواحد منهم حكى عن بنت عمه إللي كان بيحبها وكانت محتاجة مال وهو راودها عن نفسها مقابل المال، زي ما شرحنا قبل كده لو تفتكروا\nففي فعلا نساء ممكن تتجه للطريق ده بسبب قلة المال، فالصدقة هنا عليها ممكن تكون سبب في إنها تترك الطريق ده.\nأما الرجل الغني فلما يشوف حد بيتصدق ممكن يراجع نفسه ويخرج زكاة ماله أو يخرج صدقات،\nفالرجل كانت نيته صادقة ومخلص وكان بيحاول إن الصدقة تقع في يد إللي يستحقها، عشان كده ربنا تقبل صدقته\nفالمهم يا جماعة صدق النية والإخلاص حتى لو الصدقة لم تقع في موضعها الصحيح على الرغم من اجتهادنا،\nفاحنا مش دايما هنعرف حكمة ربنا في الأمور إللي بتحصل حوالينا، عشان كده لازم نسلم أمرنا لله،\nوالواحد بصدق نيته وإخلاصه ممكن يكون سبب في خير كتير ميعرفش عنه حاجة في علم الغيب،\nهو الرجل ده كان هيعرف الحكمة من الأحداث إلا من خلال الرؤيا، وإلا كان ساعتها هيفضل في حيرة ومفكر إن صدقته لم تُقبل\nفكده برده في النهاية هنرجع لحديث رسول الله ﷺ:\n\"لا تحقرَنَّ من المعروفِ شيئًا\"\nوهنرجع كمان لقول أبي موسى الأشعري:\nاذْكُرُوا   صَاحِبَ   الرَّغِيفِ \nمصادر جزء النهاردة في التعليقات"}, {"n": 249, "l": "الجزء 223 | احداث السنه العاشره من الهجرة | حجة الوداع الجزء الأول | بداية الرحله", "u": "https://www.facebook.com/groups/710210019782034/permalink/837762113693490/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائتين_وثلاثة_وعشرين\n#أحداث_السنة_العاشرة_من_الهجرة\n#حجة_الوداع_الجزء_الأول\n#بداية_الرحلة\nاتكلمنا في الأجزاء الأخيرة عن بعض قصص الصحابة مع رسول الله ﷺ وبعض قصص الحديث النبوي، وأنا بصراحة كنت محتار أكمل في قصص الحديث النبوي والصحابة ولّا أدخل في الكلام عن حجة الوداع\nفلقيت إنها فرصة إننا نعيش نفس لحظات ذي الحجة مع رسول الله ﷺ،\nسبحان الله، أنا لو حاولت أرتب الأحداث وأنظمها بحيث يبقى في تزامن بين حجة الوداع وبين أيام ذي الحجة إللي احنا فيها دلوقتي دي مش هعرف أضبطها كده\nفهو بترتيب من ربنا سبحانه، فعشان كده هنتكلم عن الحجة الأولى والوحيدة التي حجها رسول الله ﷺ في الإسلام\nفي أواخر شهر ذي القعدة من السنة العاشرة من الهجرة قرر رسول الله ﷺ الخروج للحج،\nوعرّف الناس إنه هيخرج للحج عشان إللي عايز يخرج للحج معاه يبدأ يتجهز،\nفوصل الخبر للناس حول المدينة فتجهزوا للخروج للحج مع رسول الله ﷺ،\nخرج رسول الله ﷺ من المدينة باتجاه مكة ومعه زوجاته التسع كلهن وابنته فاطمة،\nوخرج معه الصحابة رضي الله عنهم، وكل ده كان في آخر خمس أيام من شهر ذي القعدة، وكان يوم سبت،\nخرج من المدينة بعد ما صلى الظهر أربع ركعات وذكّر الناس ووعظهم وعلمهم كيفية مناسك الحج،\nوَصَل رسول الله ﷺ لمنطقة اسمها ذي الحُلَيْفَة، أو ما يُسمى في عصرنا دلوقتي آبار علي،\nوالمنطقة دي هي ميقات أهل المدينة، يعني المكان إللي يبدأ فيه الإحرام.\n☆الإحرام معناه:\n نية الدخول في حج أو عمرة، زي كده لما نيجي نصلي بتبقى نيتنا الدخول في الصلاة لما نقول تكبيرة الإحرام،\nفكذلك الإحرام هو نية الدخول في حج أو عمرة لما نوصل المكان إللي هيبدأ فيه الإحرام\nوالأصل في الإحرام المنع، \nيعني الواحد هيمتنع عن أشياء معينة هي في العادي حلال، لكنها في الوقت ده بالذات حرام عليه\nوالإحرام هو أول ركن من أركان الحج، يعني أول حاجة يبدأ بيها إللي عايز يحج أو يعمل عمرة\nوالنية محلها القلب ، والتلفظ بها بدعة،\nيعني إن الواحد ينوي الحج أو العمرة من قلبه عند الميقات، ولا ينطق بالنية دي؛\nلأن رسول الله ﷺ لم يتلفظ بالنية سواء في الحج والعمرة أو في أي عبادة تانية، يعني مقلش نويت الحج والعمرة، أو نويت أصلي كذا وكذا أو....أو...\nلأ، نية أي عمل صالح تكون في القلب\nلما وصل رسول الله ﷺ لذي الحُلَيْفَة في نفس يوم السبت إللي خرج فيه؛ صلى فيها العصر ركعتين والمغرب ثلاث ركعات والعشاء ركعتين، وصلى فيها فجر يوم الأحد،\nوبدأ الناس يأتوا من كل مكان، فجاء خلق كثير، وطبعا مفيش ولا واحد مشرك كلهم مسلمين،\nلأن زي ما قلنا في أحداث السنة التاسعة نزلت الآية إن المشركين ممنوع يدخلوا مكة تاني\nفي الليلة إللي نامها رسول الله ﷺ دي جاءه جبريل عليه السلام في المنام وأمره إنه يصلي في واد العقيق،\nقال رسول الله ﷺ:\n\" أَتَانِي اللَّيْلَةَ آتٍ مِن رَبِّي، فَقالَ: صَلِّ في هذا الوَادِي المُبَارَكِ، وقُلْ: عُمْرَةً في حَجَّةٍ\"\nوواد العقيق ده بيمر بمنطقة ذي الحُلَيْفَة إللي قاعد فيها رسول الله ﷺ دلوقتي وهيُحرم منها،\nعشان كده العلماء قالوا إنه يُستحب للي عايز يحج أو يعتمر من منطقة المدينة إنه يصلي ركعتين في مسجد ذي الحُلَيْفَة قبل إحرامه أو يصلي فريضة إن كان وقت صلاة فريضة وبعدين يُحرم،\nزي ما رسول الله ﷺ عمل، فهو صلى الظهر في يوم الأحد ده وأحرم بعد صلاة الظهر مباشرة.\n◇هو احنا مش قلنا إن النية محلها القلب؟\n إيه بقى إللي جاء في الحديث دلوقتي ده معناه إيه\n\"وقُلْ: عُمْرَةً في حَجَّةٍ\"\nده معناه إنه يذكر النُّسُك في التّلبيَة، يعني يقول:\nاللهم لبيك عمرة، أو اللهم لبيك حج، أو اللهم لبيك حج وعمرة،\nوهي دي إللي ربنا أمر رسول الله ﷺ بيها، أمره إنه يَقْرِن الحج والعمرة مع بعض، وده اسمه حج القِرَان،\nفكده تبقى دي هي العمرة الرابعة التي اعتمرها رسول الله ﷺ،\nالأولى كانت عمرة الحديبية إللي أهل مكة منعوه فيها، والتانية كانت السنة إللي بعدها واسمها عمرة القضية،\nوالعمرة الثالثة بعد فتح مكة بعد ما رجع من حنين ووزع الغنائم وكان اسمها عمرة الجُعرانة،\nوالعُمرة الأخيرة هي إللي كانت مع الحج\nيبقى رسول الله ﷺ أحرم بالحج والعمرة مع بعض،\nولأن ده حج قِران فيجب على الحاج إنه يقدم هَدْي، والهدي معناه البهيمة من الأنعام سواء إبل أو بقر أو غنم زي الأضحية كده،\nوالحاج عليه هَدي واحد فقط، ولو زوّد فله أجر أعلى،\nفرسول الله ﷺ ساق الهدي معاه وكان الهدي إللي ساقه معاه ثلاثاً وستين ناقة،\nوجاء علي رضي الله عنه من اليمن بسبعة وثلاثين ناقة، فبقى العدد كله مائة بَدَنَة\n☆طيب لو واحد ملقاش هَدي يعمل إيه\nيعمل زي ما ربنا قال في سورة البقرة:\n\" فَمَن لَّمْ يَجِدْ فَصِيَامُ ثَلَاثَةِ أَيَّامٍ فِي الْحَجِّ وَسَبْعَةٍ إِذَا رَجَعْتُمْ تِلْكَ عَشَرَةٌ كَامِلَةٌ\"\nيعني إللي مش هيلاقي هدي سواء لأن مفيش مال أو مفيش حيوان يبقى الحاج يصوم ثلاثة في الحج يكون أخر يوم للصيام هو يوم عرفة،\nولما الحاج يرجع لبلده يصوم سبع أيام تانية\n☆ملحوظة:\nالهدي ده خاص بكل حد غير أهل مكة، يعني أهل مكة المستوطنين مكة ليس عليهم هدي ولا صيام،\nلكن أي حد جاي من برة مكة عليه هدي،\nولو ملقاش يبقى صيام العشر أيام زي ما قلنا\nربنا بيقول في باقي الآية إللي قلناها:\n\"ذَلِكَ لِمَنْ لَمْ يَكُنْ أَهْلُهُ حَاضِرِي الْمَسْجِدِ الْحَرَامِ\"\n◇طيب لو واحد مقيم في مكة بسبب عارض، يعني بسبب عمل أو دراسة أو...أو...هل كده يبقى معلهوش هدي زي أهل مكة\nهنا الموضوع يختلف، أي واحد موجود في مكة مقيم إقامة عارضة لسبب وهيترك البلد ويمشي ولو بعد فترة وعايز يحج حج قِران أو تَمَتُّع يبقى يجب عليه هدي،\nلكن لو كان الحج مُفرِد يبقى معلوش هدي، ولو قدم هدي أفضل، لكن مش واجب زي القِران والتَمَتُّع.\n☆حج القِران وحج التمتع بيبقى حج وعمرة مع بعض،\nوالفرق بين حج القران والتمتع هنعرفه الجزء الجاي إن شاء الله لما ييجي الموقف بتاعه مع الصحابة\nأما حج المُفرِد فبيكون حج فقط من غير عمرة\nيبقى كده يا جماعة رسول الله ﷺ خرج من المدينة راح ذي الحُلَيْفَة بات فيها وصلى تاني يوم الظهر واغتسل وتطيب وأَحرم ولبس ملابس الإحرام إللي هي الإِزَار والرّداء؛ \nلأن لا يجوز للمحرم إنه يلبس المخيط من الثياب،\n وركب رسول الله ﷺ الدابة ولبى تلبية حج القِران اللهم لبيك حج وعمرة، وبعدها قال تلبية التوحيد:\n\" لبيك اللهم لبيك، لبيك لا شريك لك لبيك، إن الحمد والنعمة لك والملك لا شريك لك\"\nوساق مائة من الهدي عشان يذبحها قربة لله، \nتماما كده\n☆ملحوظة:\nرسول الله ﷺ لما تطيب كان على جسده، وقبل عقد نية الإحرام ولم يضع الطيب على الإزار أو الرداء؛ لأن لا يجوز وضع الطيب أو العطر على ملابس الإحرام أو بعد عقد نية الإحرام\nوبالنسبة للنساء في الحج فهي برده نفس الموضوع، زي ما رسول الله ﷺ عمل كده، تغتسل وتصلي وتعمل كل إللي رسول الله ﷺ عمله حتى لو كانت نفساء أو حائض، طبعا ما عدا الصلاة وإنها لا تتطيب، يعني متحطش عطر؛\nلأن العطر للنساء محرم إذا كانت هتمشي وسط رجال،\nومن المواقف إللي حصلت في ذي الحليفة إن أسماء بنت عميس البحرية إللي اتكلمنا عنها قبل كده وقلنا إنها كانت زوجة جعفر بن أبي طالب وهي حاليا متزوجة من أبي بكر الصديق رضي الله عنه كانت حامل وولدت طفل اسمه محمد،\nيعني هي كانت خارجة للحج وهي حامل فولدت\nفأمرها رسول الله ﷺ بالاغتسال وإنها تلبي تلبية الحج عادي،\nفالغسل هنا للاستحباب مش الوجوب، فلو كانت المرأة نفساء أو حائض تغتسل وبعدين تلبي تلبية الحج،\nوبالنسبة لملابس المرأة في الإحرام فهي تلبس حجابها الشرعي عادي، ولا يشرط لبس معين زي الرجل كده، وطبعا اللبس إللي هتلبسه ميكنش فيه أي زينة ولا يلفت النظر ولا شكله جميل،\nلكنها فقط لا تلبس《النقاب أو القفازين》،\nلأن رسول الله ﷺ قال:\n\"لا تنتقب المرأة المحرمة ولا تلبس القفازين\"\nالنقاب بيبقى قماشة كده منقوبة أو مخرومة خرمين أو خرم واحد، أو اسمه برقع وبيكون متفصل على أد الوجه، \nزي ما القفاز أو الجاونتي متفصلين على اليد،\nده إللي مينفعش المرأة تلبسه،\nمحدش هنا ييجي يقول إن ده دليل على عدم فرضية النقاب\nده كده معناه بقى إن رسول الله ﷺ لما أمر إن الرجال ميلبسوش المخيط يبقى هيمشوا عريانين\nقال إن الرجال ميلبسوش المخيط بس يلبسوا لبس تاني يغطوا بيه جسمهم،\nكذلك برده المرأة مش هتلبس النقاب لكن هتغطي وجهها في الإحرام زي ما عملت السيدة عائشة رضي الله عنها وباقي زوجات رسول الله ﷺ ونساء الصحابة،\nقالت السيدة عائشة:\n\" كان ‏الرُّكبان يمرون بنا ونحن مُحرمات مع رسول الله ﷺ فإذا حاذوا بنا سدلت ‏إحدانا جلبابها من رأسها على وجهها فإذا جاوزونا كشفنا\"\nوقالت أسماء بنت أبي بكر نفس الكلام إللي قالته عائشة،\nوالمعنى إنهم وهم محرمات مع رسول الله ﷺ وكانوا كاشفين لوجوههن فإذا اقترب منهن الرجال تقوم كل واحدة منزلة من على رأسها من جلبابها إللي يغطي وجوههن،\nأو بيغطوا وجوههن وأيديهن بالخمار إللي لابسينه،\nوخدوا بالكم إن رسول الله ﷺ كان شايف فعل الصحابيات وفعل السيدة عائشة وباقي زوجاته،\nيعني لو كان فعلهم غلط أو مثلا مش فرض كان رسول الله ﷺ قال لهم يخففوا شوية عن نفسهم بدل ما كل شوية يرفعوا وينزلوا،\nلكن ده محصلش ورسول الله ﷺ لم يتكلم فده معناه إن فعلهم كان صحيح \nوالحكمة في عدم لبس المرأة النقاب والقفازين بالذات في وقت الإحرام هي برده نفس الحكمة من النهي ‏عن جميع محظورات الإحرام للرجل والمرأة\nوهي التعبد لله بذلك\nيعني الاستجابة لأوامر الله، قال مفيش تطيب ومفيش قص شعر ومفيش ...ومفيش....كل ده عشان نفهم إن الأمر كله لله وإن احنا ملناش غير إننا نطيع أمر الله وبس\nخرج رسول الله ﷺ والصحابة والصحابيات على الهيئة إللي احنا شرحناها دي متجهين لمكة،\nوهم يُلبُّون بتلبية التوحيد بعد ما كان عمرو بن لحي أضاف لها تلبية الشرك وكانت العرب على مر السنين بيرددوها،\nفرسول الله ﷺ دلوقتي قائد قافلة الحج دي بيبلي بتلبية التوحيد إللي قعد ثلاثة وعشرين سنة يناظر ويحاور ويقاتل عشان يوصلها لكل الجزيرة العربية\nدي يا جماعة أول سنة يُقام فيها الحج بدون أي شرك أو مشركين من زمن عمرو بن لحي،\nفتخيلوا مشاعر رسول الله ﷺ وهو في طريقه للحج بعد ما خلاص حقق هدفه بعد سنين طويلة من المعاناة\nيعني احنا مثلا بنشتاق ونفسنا نروح للحج،\nوالناس إللي بتروح للحج بتبقى فرحانة إنها هتؤدي الفريضة العظيمة دي،\nفتخيلوا بقى مشاعر رسول الله ﷺ بالذات إللي محجش قبل كده، وحتى العمرات إللي عملها قبل كده كان فيها مشركين بيلبوا تلبية الشرك،\nدلوقتي مفيش الكلام ده خلاص، \nرسول الله ﷺ حقق إللي كان بيحارب وبيعاني السنين إللي فاتت دي كلها عشانه،\nالناس جاية من كل اتجاه وهي تلبي تلبية التوحيد فقط،\nماهو في حج السنة التاسعة تم الإعلان إن محدش من المشركين هيدخل مكة تاني خلاص\nمهما حاولنا نتخيل مشاعر رسول الله ﷺ في موقف زي ده مفيش كلمات تقدر توصف مشاعر رسول الله ﷺ في اللحظة دي\nاستمرت الرحلة دي حوالي أسبوع، يعني هو خرج من ذي الحليفة يوم الأحد وصل مكة يوم الأحد إللي بعده،\nحصل إيه بقى بعد ما وصل مكة؟\nده إللي هنعرفه الجزء الجاي إن شاء الله \nمصادر جزء النهاردة في التعليقات"}, {"n": 250, "l": "الجزء 224 | حجة الوداع الجزء الثاني | الاحداث بعد الوصول إلى مكه", "u": "https://www.facebook.com/groups/710210019782034/permalink/837762763693425/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائتين_وأربعة_وعشرين\n#أحداث_السنة_العاشرة_من_الهجرة\n#حجة_الوداع_الجزء_الثاني\n#الأحداث_بعد_الوصول_إلى_مكة\nاتكلمنا المرة إللي فاتت عن خروج رسول الله ﷺ للحج ووقفنا عند وصول رسول الله ﷺ لمكة،\nقبل ما رسول الله ﷺ يوصل لمكة وفي منطقة اسمها سَرِف السيدة عائشة حاضت،\nومنطقة سَرِف دي بعيدة عن مكة بحوالي ستة عشر كيلو متر تقريبا\nالمهم، \nوصل رسول الله ﷺ والصحابة معاه لمكان اسمه ذي طُوَى قريب جدا من مكة، على أطراف مكة كده،\nوهو نفس المكان إللي رسول الله ﷺ دخل منه مكة في عام الفتح لو تفتكروا\nوصل هناك ليلة الأحد الرابع من ذي الحجة في السنة العاشرة من الهجرة، وبات في ذي طوى،\nصلى الفجر في ذي طُوى واغتسل وتوجه لبيت الله الحرام ووصل وقت الضحى، \nلما وصل طاف بالبيت سبع أشواط، يعني قعد يدُور حوالين الكعبة سبع مرات، وده كده اسمه طواف القُدُوم،\nيعني إللي ييجي للحج أو العمرة أول حاجة يعملها إنه يطوف حول الكعبة سبع أشواط\nبعد الطواف، رسول الله ﷺ سعى بين الصفا والمروة، يعني قعد يمشي في الطريق إللي كان بين الصفا والمروة،\nأول ما رسول الله ﷺ قرّب من جبل الصفا قرأ:\n\"إِنَّ الصَّفَا وَالْمَرْوَةَ مِنْ شَعَائِرِ الله فَمَنْ حَجَّ الْبَيْتَ أَوِ اعْتَمَرَ فَلَا جُنَاحَ عَلَيْهِ أَنْ يَطَّوَّفَ بِهِمَا\"\nفبدأ في السعي بالصفا زي ما ربنا بدأ به في الآية،\nيعني مَشى مشيا سريعا في الطريق إللي بين جبل الصفا وجبل المروة سبع أشواط،\nوابتدأ بالصفا وطلع عليه لحد ما شاف الكعبة فوّحد الله وكبّره، يعني قال:\nلا إله إلا الله والله أكبر،\nوبعد كده قال:\n\"لا إله إلا الله وحده لا شريك له، له المُلْك وله الحمد، وهو على كلِّ شيءٍ قدير، لا إله إلا الله وحده، أَنْجَز وعدَه، ونصر عبدَه، وهَزَم الأحزاب وحدَه\"\n♡واخدين بالكم من كلام رسول الله ﷺ \n《أنجز وعده》\n《 ونصر عبده》\n《وهزم الأحزاب وحده》\nأكيد اللحظة دي لحظة مَهيبة في حياة رسول الله ﷺ\nأول مرة طلع على جبل الصفا كان لما أعلن عن بعثته ﷺ وأخبر الناس إنه رسول من عند الله وساعتها كذبوه،\nالمرة التانية كان لما دخل مكة فاتحا وكان فيها المشركين،\nدلوقتي دي المرة الثالثة على جبل الصفا، بس المرة دي كل الموجودين قصاده على الإسلام\nكل إللي ربنا وعد به رسول الله ﷺ تحقق، \nونصره على كل أعدائه، وهزم كل جموع الكفار إللي اتجمعوا ضده ﷺ،\nالفرق بين أول مرة إللي حصل فيها تكذيب لرسول الله ﷺ وكان واقف لوحده والكل بيعاديه وبين وتالت مرة إللي كان فيها الإسلام مُسيطر على كل الجزيرة العربية وكل الناس حواليه وهو القائد؛ ثلاثة وعشرين سنة\nلعل رسول الله ﷺ في اللحظة دي كان بيتذكر أحداث الثلاث وعشرين سنة إللي فاتت،\nعمه أبو لهب إللي كان أول واحد كذبه....أبو جهل....\nعتبة بن ربيعة...الوليد بن المغيرة...عقبة بن أبي معيط....\nالنضر بن الحارث....وغيرهم من مشركي مكة إللي كانوا بيحاربوه،\nولعله تذكر رحلته المؤلمة للطائف، وخروجه يوم الهجرة وكل أهل مكة خرجوا يطاردوه عشان المكافأة،\nولعله تذكر أصحابه إللي ماتوا شهداء ومحدش منهم شاف اللحظة دي، \nزي سمية وزوجها ياسر، وزي مُصعب بن عمير إللي قُتل في غزوة أحد وهو مفكر إن رسول الله ﷺ قتل،\nولعله.....ولعله.....أحداث كتير جدا في الثلاث وعشرين سنة دول،\nالطريق مكنش سهل خالص\nرسول الله ﷺ تألم وتأذى وفَقَد أصحابه وضحّى هو والصحابة عشان يوصلوا للمكان ده،\nاحنا دايما بنشوف النهاية الجميلة والإنجاز إللي الشخص حققه،\nلكن مش بنركز أو مش بنهتم أوي بالمعاناة إللي عاشها الشخص ده عشان يوصل للإنجاز بتاعه، \nرسول الله ﷺ قعد ثلاثة وعشرين سنة لحد ما وصل للقمة في بناء الأمة، \nفما بالكم بغيره محتاج كم سنة؟\nومحتاج تضحيات أد إيه؟\nومحتاج جهاد للنفس والتربية الإيمانية أد إيه؟\nاحنا ممكن منعرفش محتاجين زمن أد إيه عشان نوصل للي وصل له رسول الله ﷺ والصحابة،\nلكن احنا عارفين ومتأكدين إن إللي هيعمل نفس الخطوات إللي عملها رسول الله ﷺ وهيمشي في نفس طريقه هيوصل في يوم من الأيام للي وصل له رسول الله ﷺ\nرسول الله ﷺ وحّد وكبّر وقال لا إله إلا الله وحده لا شريك له..... ثلاث مرات وهو على جبل الصفا وكان بيدعو بين كل مرة والتانية،\nوبعدين نزل من الصفا ومشي في الطريق المُمْتد بين الصفا والمروة لحد ما طلع على جبل المروة وعمل نفس إللي عمله على جبل الصفا،\nوحّد الله وكبّر وقال: لا إله إلا الله وحده لا شريك له.....ثلاث مرات ودعا بينهم،\nوده كده اسمه الشوط الأول،\nوبعد كده نزل من المروة وتوجه للصفا وعمل نفس إللي عمله قبل كده، وده يبقى الشوط الثاني،\nواستمر على كده لحد ما خلص السبع أشواط\n☆ملحوظة:\nمفيش أدعية معينة أثناء السعي غير إللي عمله رسول الله ﷺ على الصفا وعلى المروة،\nفالحاج يدعي باللي هو عايزه من غير ما يلتزم بدعاء معين، وطبعا مفيش أي دليل على إن واحد يقعد يدعي وإللي حواليه يردوا وراه أو يُأَمّنوا على دعائه\nكل ده مخالف لسنة رسول الله ﷺ \nبعد ما رسول الله ﷺ خلص السبع أشواط من السعي وهو على جبل المروة في آخر شوط قال للناس:\n\"مَن لكم منكم ساق هَدْيًا فلْيحلِلْ ولْيجعَلْها عمرةً\"\nيعني هو قال للصحابة إللي كانوا ناويين الحج ومكنش معاهم هدي إنهم يفسخوا نية الحج ويحولوها لنية عمرة، \nفسألوه:\n\"حِلُّ مَاذَا؟!\"\nيعني إيه بالضبط المباح لنا لما نتحلل، فقال لهم كل شيء حلال،\nيعني يعملوا كل حاجة كانت مُحرمة عليهم وقت الإحرام زي حلق الشعر أو التقصير أو جماع النساء وغيره، \nوبعد كده يُحرِموا مرة تانية من مكة زي ما هنشوف بعدين، عشان يؤدوا مناسك الحج من غير ما يحتاجوا يرجعوا لأي مكان من أماكن الإحرام إللي هي مواقيت الإحرام،\nوده كده يبقى اسمه حج التّمَتُّع،\nيعني إن الشخص يعمل عمرة الأول قبل الحج وبعدين يتحللل منها ثم يُتبِع العمرة بالحج، \nسواء بقى العمرة دي في نفس زمن الحج زي ما رسول الله ﷺ قال للصحابة كده،\nأو في أشهر الحج إللي هم شوال وذي القعدة وذي الحجة،\nفالواحد بيعمل العمرة في الشهور دي وهو ناوي الحج بعدها  فيتحلل بعد العمرة ويستنى الحج، ولما ييجي شهر ذي الحجة يُحرِم ويخرج للحج،\nوهو اسمه حج التمتع لأن الحاج هنا بيتمتع بمحظورات الإحرام بين العمرة والحج لما بيتحلل من العمرة،\nبعكس إللي بيحج حج القِران، فهو بيعمل الحج والعمرة كلهم بإحرام واحد من غير تحلل\nوالسبب بقى في أمر رسول الله ﷺ للناس إللي لم يسوقوا الهدي إنهم يفسخوا نيتهم للحج ويجعلوها عمرة وبعدين يحجوا إنه كان عايز يعرّفهم إنه يجوز عمل عُمرة في زمن الحج؛ بعكس إللي كانوا عليه في الجاهلية،\nيعني هم في الجاهلية كان عندهم اعتقاد إن زمن الحج لا يجوز عمل فيه عمرة،\nوكان عندهم إن ده من أفجر الفجور من أيام الجاهلية، إزاي يفسخوا نيتهم من الحج للعمرة، ويعملوا عمرة في زمن الحج\nفرسول الله ﷺ بيوضح لهم بطريقة عملية إن ده جائز عادي في الإسلام\n وفعلا كان في ناس مكنتش متقبلة الموضوع، إزاي يعني نقطع الإحرام ونستمتع بالنساء وبعدين نروح نحج ونقف على عرفات؟!!\nفلما وصل الكلام لرسول الله ﷺ قال:\n\"واللهِ لقد علِمْتُم أنِّي أتقاكم ولو علِمْتُ أنَّكم تقولون هذا ما سُقْتُ الهَدْيَ فاسمَحوا بما تُؤمَرون به\"\nيعني هو لو مكنش ساق الهدي كان عمل عمرة الأول وبعدين حج، يعني كان عمل حج التمتع،\nوفي رواية تانية قال:\n\"لو استقبلتُ من أمري ما استدبرت لجعلتُها عمرة ولَمَا سُقْت الهدي\"\nيعني لو كنت أعرف المشقة إللي هيحس بيها أصحابي بسبب انفرادهم عني بالفسخ لدرجة إنهم توقفوا وترددوا في فسخ النية؛\nمكنتش سُقْت الهدي وكنت عملت زيهم: فسخت النية وتحللت وبعدين حجيت،\nفاللي ترددوا كانوا عايزين يعملوا زي رسول الله ﷺ بالضبط ويتبعوه في كل شيء، \nفلما شافوا إنه هيعمل حاجة غير إللي هم هيعملوها بقى الموضوع فيه مشقة على أنفسهم، بالإضافة إنهم كانوا مستغربين الموضوع،\nفلما قال لهم الكلام ده رضوا وطابت نفوسهم وعملوا إللي قال لهم عليه\nده كده كان معنى حج التمتع باختصااااار\nحج القِران بقى بيكون كله بإحرام واحد من غير تحلل،\nزي رسول الله ﷺ وباقي الصحابة إللي كان معهم الهدي\nقال لهم رسول الله ﷺ إن إللي معاه هَدْي زيه كده ﷺ يخليهم زي ماهمّ: نيتهم حج مع عمرة.\nإللي سمعت الحوار بين رسول الله ﷺ والصحابة وبتحكيه هي السيدة عائشة، بتقول:\n\"خَرَجْنَا مع رَسولِ اللَّهِ ﷺ في أَشْهُرِ الحَجِّ، ولَيَالِي الحَجِّ، وحُرُمِ الحَجِّ، فَنَزَلْنَا بسَرِفَ، \nقالَتْ: فَخَرَجَ إلى أَصْحَابِهِ، \nفَقالَ: مَن لَمْ يَكُنْ مِنكُم معهُ هَدْيٌ، فأحَبَّ أَنْ يَجْعَلَهَا عُمْرَةً فَلْيَفْعَلْ، ومَن كانَ معهُ الهَدْيُ فلا\"\nفهم كده حولوا حجهم من القِران إلى التمتع، \nفنقدر نقول كده ببساطة إن حج التمتع بيتعمل فيه عمرة الأول بكامل أركانها وبيحصل تحلل منها قبل الحج،\nأما حج القِران فبيكون فيه الحج الأول ومفيش فيه تحلُّل  وبيدخل فيه أعمال العمرة\nبعد ما رسول الله ﷺ قال الكلام ده للصحابة دخل على السيدة عائشة في الخيمة لقاها بتعيط\nفقال لها:\n\"ما يُبْكِيكِ يا هَنْتَاهُ؟\"\nهنتاه معناها بلهاء، يعني نسبة إلى قلة المعرفة بمكائد الناس وشرورهم، أو معنى تاني: يا هذه،\nفقالت لرسول الله ﷺ:\n\"سَمِعْتُ قَوْلَكَ لأصْحَابِكَ فَمُنِعْتُ العُمْرَةَ\"\nيعني أنا سمعت إللي قلته للصحابة وأنا مش هقدر أعمل زيهم،\nفسألها:\nوما شَأْنُكِ؟ \nيعني ليه مش هتقدري تعملي كده، فقالت\nلا أُصَلِّي.\nيعني جاءها الحيض زي ما قلنا في البداية خالص\nفقالَ لها: \nفلا يَضِيرُكِ، إنَّما أَنْتِ امْرَأَةٌ مِن بَنَاتِ آدَمَ، كَتَبَ اللَّهُ عَلَيْكِ ما كَتَبَ عليهنَّ، فَكُونِي في حَجَّتِكِ، فَعَسَى اللَّهُ أَنْ يَرْزُقَكِيهَا.\nيعني رسول الله ﷺ بيخفف عنها وبيقولها إن مش هي الوحيدة إللي بيحصل معاها كده، ده كل النساء بيحصل معاهم كده،\nفخليكي زي مانتي في الحجة بتاعتك عسى الله ربنا يقدر لك العمرة بعدها، \nوأمرها إنها تعمل كل مناسك الحج إلا الطواف بالبيت الحرام، فالحائض تنتظر لحد ما تطهر وبعدين تطوف بالبيت\nوفعلا في نهاية الحج ورسول الله ﷺ راجع للمدينة بعد ما السيدة عائشة طهرت من الحيض وأنهت حجتها أمر رسول الله ﷺ عبد الرحمن بن أبي بكر أخو عائشة إنه ياخدها ويتوجهوا لمنطقة التنعيم إللي هي خارج الحرم عشان السيدة عائشة تُحرم من هناك للعمرة إللي كانت عايزة تعملها منفردة زي باقي الصحابة بس معرفتش بسبب الحيض،\nوبعد ما يخلصوا يرجعوا لرسول الله ﷺ للمكان إللي مستنيهم فيه عشان يرجعوا للمدينة\nيبقى كده يا جماعة عندنا مجموعتين، ناس تحللوا من الإحرام وهم إللي مكنوش ساقوا الهدي،\nوالمجموعة التانية إللي ساقوا الهدي واستمروا على إحرامهم ودول كان قائدهم رسول الله ﷺ،\nقعدوا كلهم في مكة أربعة أيام، من يوم الأحد الرابع من ذي الحجة لحد يوم الخميس الثامن من ذي الحجة،\nواليوم ده اسمه يوم التَّرْوِيَة\nليه اسمه كده وإيه إللي بيحصل فيه؟\nده إللي هنعرفه 《بكرة》 إن شاء الله \nجزء النهاردة صغير عشان هنقسم الأحداث على مراحل،\nالمرحلة الأولى إللي اتكلمنا عنها المرة إللي فاتت كانت الرحلة من المدينة لحد الوصول إلى المكة،\nوالمرحلة التانية إللي اتكلمنا عنها النهاردة كانت الأحداث بعد  بعد الوصول إلى مكة،\nالمرحلة الثالثة إللي هنتكلم عنها بكرة إن شاء الله هتكون عن بداية أيام الحج\nمصادر جزء النهاردة في التعليقات"}, {"n": 251, "l": "الجزء 225 | حجة الوداع الجزء الثالث | يوم عرفه", "u": "https://www.facebook.com/groups/710210019782034/permalink/837763307026704/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائتين_وخمسة_وعشرين\n#أحداث_السنة_العاشرة_من_الهجرة\n#حجة_الوداع_الجزء_الثالث\n#يوم_عرفة\nقبل ما نبتدي جزء النهاردة عايز أوضح نقطة عشان اتكرر السؤال عنها،\nبالنسبة لحج المتمع فهو عليه هدي،\nلكن أنا مأجلة الكلام عن الهدي لحد ما ييجي وقته،\nهتبقى زي حلقة كاملة كده عن ذبح الهدي،\nومين إللي عليه الهدي ومكان ذبح الهدي فين بالضبط،\nولو تفتكروا أنا قايلة في الجزء الأول من الرحلة إن المتمتع يجب عليه هدي، \nبس أنا مذكرتش التفصيل بتاعه، عشان زي ما قلت هتبقى حلقة كاملة عن الهدي إن شاء الله \nندخل بقى في جزء النهاردة\nقلنا المرة إللي فاتت إن رسول الله ﷺ قعد في مكة أربع أيام لحد اليوم الثامن من ذي الحجة،\nواليود ده اسمه يوم 《التَّروِيَة》\nوهو اليوم إللي بيُحرِم فيه الحجاج للحج، وبيخرجوا وقت الضحى وبيتجهوا لمِنَى عشان يبيّتوا فيها،\nواتسمى بالاسم ده لأن أهل مكة كانوا يرتوون من الماء فيه لما بعد مِنَى، \nيعني بياخدوا معاهم مية تكفيهم للمبيت بمنى ومن بعدها الوقوف بعرفة عشان المية كانت قليلة في مِنَى،\nوقيل إن سبب التسمية إن إبراهيم عليه السلام رأى رؤيا ذبح ابنه إسماعيل في ليلة اليوم الثامن من ذي الحجة،\nفلما أصبح بقى يَروِي في نفسه أهو حلم؟ أم من الله؟ فسُمّيَ يوم التروية\nيبقى في يوم التروية في وقت الضحى خرج رسول الله ﷺ  باللي معاه من المسلمين في اتجاه مِنى،\nالصحابة إللي كانوا تحللوا من العمرة هيُحرِموا من مساكنهم إللي هم قاعدين فيها وكانوا نزلوا مكان اسمه الأبْطُح،\nفقال لهم رسول الله ﷺ إنهم يحرموا من الأبطح،\nفأحرموا منها وعملوا نفس إللي عملوه عند الميقات من اغتسال وتطيب ولبس الاحرام و...و....إللي اتكلمنا عنه في الجزء الأول من بداية الرحلة، \nويدخل معاهم برده إللي عايز يحج من أهل مكة هيعمل زيهم بالضبط،\nأما بقى الحاج المُفرِد والمُقرِن فهو باقي على إحرامه الأول فهيخرج مباشرة لمِنى،\nوهو ده إللي عمله رسول الله ﷺ، خرج على طول إلى منى في وقت الضحى،\nمِنَى ده وادي يحيط بيه الجبال، موجود على الطريق بين مكة وجبل عرفة،\nووادي منى بعيد عن المسجد الحرام بحوالي ستة كيلو متر،\nواتسمت مِنى بالاسم ده بسبب كثرة الدماء التي تُراق فيها، والمقصود هنا دماء الهَدْي؛ لأن الهدي بيُذبح في منى،\nوده قول جمهور أهل اللغة،\nوفي أقوال تانية زي: إن ربنا يَمُنّ على عباده بالمغفرة في منى، وغيرها من الأقوال\nوصل رسول الله ﷺ منى وقعد فيها طول اليوم، وصلّى فيها  بالمسلمين إماما الظهر والعصر والمغرب والعشاء، \nصلاهم قصر في وقتهم، يعني صلى الظهر ركعتين في قت الظهر،\nوصلى العصر ركعتين في وقت العصر،\nالمغرب مفهوش قصر فصلاه ثلاث ركعات في وقتها،\nالعشاء صلاها ركعتين في وقتها، فهو مجمعش بين الصلوات\nوطبعا المسلمين كلهم صلوا وراه قصر حتى أهل مكة، فلو كان مثلا يجب عليهم التمام كان طلب منهم إنهم يتموا الصلاة، لكن ده محصلش،\nفكده يبقى الصلاة في منى في يوم التروية تكون قصر سواء للحجاج من خارج مكة أو من أهل مكة نفسهم، وده قول الإمام مالك،\nفي قول تاني بيقول إن أهل مكة يتموا الصلاة عادي أربع ركعات؛ لأنهم مش على سفر، \nوالطبيعي إن الأمور تبقى على الأصل مادام مفيش دليل يقول عكس كده\nخلال اليوم كله كان رسول الله ﷺ يُكثر من التلبية:\n\"لبيك اللهم لبيك....لبيك لا شريك لك لبيك...إن الحمد والنعمة لك والملك، لا شريك لك\"\nبعد ما صلّى رسول الله ﷺ مع المسلمين العشاء باتوا كلهم في منى، \nوصلوا الفجر وانتظروا لحد ما الشمس طلعت وبعدين توجهوا لجبل عرفات\nأمر رسول الله ﷺ إنه يتعمل له قُبّة في منطقة نَمِرَة،\nوالقبة حاجة كده زي خيمة، ونمرة هي قرية صغيرة قريبة من عرفات،\nوفيها دلوقتي مسجد كبير جدا اسمه مسجد نمرة، إللي بتشوفوه في التليفزيون والحجاج بيصلوا فيه قبل ما يروحوا يقفوا على جبل عرفات\nالمهم دلوقتي إن رسول الله ﷺ توجه لمنطقة نَمِرَة، وكانت قريش في الجاهلية وإللي تبعهم لا يقفوا على جبل عرفات، \nلكن بيقفوا على المُزْدَلِفة،\nوباقي العرب بيقفوا على جبل عرفات، والمُزْدَلِفة مكان بين منى وعرفات، ويُسمى المَشْعَر الحرام،\nفقريش لما شافت رسول الله ﷺ جاي كانوا متأكدين إنه هيقف في مزدلفة زي ما كانوا بيعملوا في الجاهلية،\nلكن رسول الله ﷺ تجاوز المشعر الحرام أو المزدلفة وتوجه ناحية جبل عرفات،\nوصل رسول الله ﷺ للخيمة إللي كانت اتعملت له في قرية نمرة، فقعد هناك لحد ما دخل وقت صلاة الظهر،\nوبعدين أمر الصحابة إنهم يأتوا بناقته القَصْوَاء وركب عليها واتجه نحو بطن وادي عَرنة قريب من جبل عرفات، \nووقف هناك وخطب في الناس خطبة عرفة، وهي خطبة الوداع\nوكان عدد الحجاج أكثر من مائة ألف حاج،\nوده عدد كبير جدا، \nمن حوالي سنة واحدة تقريبا كان عدد المسلمين في غزوة تبوك ثلاثين ألف، \nدلوقتي وصلوا في بعض الروايات إلى مائة وأربعين ألف مسلم\nرسول الله ﷺ خطب الناس ثلاث خطب:\n◇الأولى: يوم عرفة. \n◇والثانية: يوم النَّحر بمِنى. \n◇والثالثة: أوسط أيام التشريق بمنى.\nبدأ رسول الله ﷺ خطبته في يوم عرفة بالحمد والثناء على الله عز وجل، وبعدها قال:\n\" أَمَّا بعد، أيّهَا النّاس، اسْمَعُوا منّي أُبّينْ لَكُمْ،\nفَإنّيَ لاَ أَدْرِي، لعَليّ لاَ أَلْقَاكُمْ بَعْدَ عَامي هَذَا، في مَوْقِفي هذا...\"\nيعني بيقولهم يسمعوا ويشوفوا إللي بيعمله عشان يطبّقوه لأن ممكن تكون دي آخر مرة رسول الله ﷺ يجتمع معاهم،\nودي إشارة منه لاقتراب أجله ﷺ،\nوكان رسول الله ﷺ في مناسك الحج بيُكثر من قوله:\n\"لِتَأْخُذُوا مَنَاسِكَكُمْ فَإِنِّي لَا أَدْرِي لَعَلِّي لَا أَحُجُّ بَعْدَ حَجَّتِي هَذِهِ\"\nأكمل رسول الله ﷺ خطبته وقال:\n\"أَيُهَا النَّاس،\nإنّ دِمَاءَكُمْ وَأمْوَالَكُمْ وَأَعْرَاضَكُمْ عَليكُمْ حَرَامٌ إلى أنْ تَلْقَوْا رَبَّكُمْ، كَحُرمَةِ يَوْمِكُمْ هَذَا في شَهْرِ كُمْ هَذَا في بَلَدِكُم هَذَا...\"\nيعني محدش يعتدي على أخوه المسلم ولا يأخذ أمواله ولا يعتدي على عرضه،\nوجعل رسول الله ﷺ حرمة الدماء والأعراض والأموال زي  حُرمة الشهر الحرام، والبلد الحرام، ويوم عرفة\nوقال:\n\"وإنكم ستلقون ربكم فيسألكم عن أعمالكم وقد بلّغت، \nفَمَنْ كَانَتْ عِنْدَهُ أَمَانةٌ فليؤُدِّها إلى مَنْ ائْتمَنَهُ عَلَيها....\"\nيعني بيؤكد على إن في يوم قيامة، وإن كل إللي الناس بيعملوه هيتسألوا عنه يوم القيامة وإنه عمل إللي عليه وبلغهم \nفأي حد عنده أمانة يرجعها لصحابها؛ لأنه لو مرجعهاش في الدنيا هيقابل ربنا وساعتها هيحاسبه وياخد من حسناته ويعطيها للي مرجعلوش الأمانة بتاعته \nأكمل رسول الله ﷺ وقال:\n\"وإن كل رِبا موضوع، ولكن لكم رءوس أموالكم لا تَظلِمون ولا تُظلَمُون، و قضى الله أنه لا ربا، \nوإن ربا عمي العباس بن عبد المطلب موضوع كله،\nوأن كل دم كان في الجاهلية موضوع وإن أول دمائكم أضع دم عامر بن ربيعة بن الحارث بن عبد المطلب، فهو أول ما أبدأ به من دماء الجاهلية....\"\nيعني رسول الله ﷺ أبطل الربا، وقال إن الواحد له رأس ماله فقط أما الزيادة فلا تحل له،\nوعشان الناس يتقبلوا الأمر وينفّذوه جعل نفسه قدوة للناس  بإنه أنهى ربا عمه العباس،\nوأبطل الثارات إللي كانت بين القبائل في جاهليتهم،\nيعني مفيش قبيلة تهجم على قبيلة عشان كان في ثأر من أيام الجاهلية،\nوبرده رسول الله ﷺ بدأ بالثأر إللي في قبيلته عشان يبقى الموضوع مقنع وسهل التنفيذ على الناس\nوقال:\n\"وإن مآثر الجاهلية موضوعة غير السِّدَانة والسقاية،\nوالعَمْد قَوَدٌ ، وشِبه العَمد ما قتل بالعصا والحجر وفيه مائة بعير فمن ازداد فهو من الجاهلية...\"\nيعني أعمال الجاهلية كلها المخالفة لشرع الله باطلة لا تصح، ومن أعمال الجاهلية الغير موضوعة السِّدانة والسقاية،\nوالسدانة معناها:\nالعناية بالكعبة والقيام بشؤونها من فتحها وإغلاقها وتنظيفها وغسلها وكِسوتها وإصلاح هذه الكسوة إذا تمزقت واستقبال زوّارها وكل ما يتعلق بذلك.\nأما السقاية معناها توفير الماء للحجيج،\nويقول رسول الله ﷺ إن العَمْد قَوَدٌ، يعني إللي بيقتل مسلم متعمد جزاؤه القتل قصاصا،\nأما القتل الغير العمد زي لو واحد ضرب واخد بعصا أو بحجارة، فالقاتل يدفع دِيَة لأهل المقتول،\nوهي مائة ناقة أو ما يساويها، ومفيش زيادة، وإللي يزوّد يبقى كده من أهل الجاهلية\nوقال رسول الله ﷺ في الخطبة:\n\"اتقوا الله في النساء فإنكم أخذتموهن بأمان الله واسْتحلَلْتم فروجهن بكلمة الله،\nولكم عليهن أن لا يُوطِئنَ فُرشَكُم أحداً تكرهونه فإن فعلن ذلك فاضربوهن ضرباً غير مبرح، ولهن عليكم رزقهن وكسوتهن بالمعروف...\"\nومعنى الكلام إن رسول الله ﷺ بيقول للناس خافوا مِن اللهِ وأدُّوا حقَّ النِّساءِ الزَّوجاتِ؛ بإنصافِهنَّ ومُراعاةِ حقِّهنَّ،\nفأنتم أخذتموهن بعهد الله واستحللتم فروجهن بالعقدِ الَّذي نشَأَ مِن كلمتَيْ إيجابٍ وقَبولٍ بين الوليِّ والزَّوجِ،\nومن حق الزوجة على زوجها إنه يأكلها ويجيب لها ملابس تلبسها،\nوبعد ما وصى رسول الله ﷺ الرجال على النساء، بيّن حق الزوج على الزوجة إنها لا يجوز إنها تُدخل بيت زوجها حد هو بيكرهه،\nولو المرأة عملت كده من حق زوجها يضربها ضرب بسيط غير مبرّح\n☆وقبل ما حد يعترض هنا ويقول ويضربها ليه أصلا والكلام ده\nهنقول هي متدخلش البيت حد بيكرهه وخلاص ومش هيبقى في ضرب ولا حاجة ولا في أي مشكلة أصلا وخلصنا\nماهو مينفعش يعني يبقى في قانون إن إللي يركن مثلا العربية بتاعته في المكان الفلاني عربيته هتتشال وهيدفع غرامة؛\nفاحنا بقى نروح نركن في المكان ده ونتخانق ليه القانون الفلاني معمول\nمتركنش وخلاص في المكان ده ويبقى مفيش مشكلة من الأساس\nفالمرأة متدخلش بيت زوجها أي حد زوجها ميحبش إنه يدخل وخلاص ومن غير وجع دماغ\nأكمل رسول الله ﷺ وقال:\n\" وَقَدْ تَرَكْتُ فِيكُمْ مَا لَنْ تَضِلُّوا بَعْدَهُ إِنِ اعْتَصَمْتُمْ بِهِ، كِتَابُ اللهِ، وَأَنْتُمْ تُسْأَلُونَ عَنِّي، فَمَا أَنْتُمْ قَائِلُونَ؟\nقَالُوا:\nنَشْهَدُ أَنَّكَ قَدْ بَلَّغْتَ وَأَدَّيْتَ وَنَصَحْتَ،\nفَقَالَ: بِإِصْبَعِهِ السَّبَّابَةِ، يَرْفَعُهَا إِلَى السَّمَاءِ وَيَنْكُتُهَا إِلَى النَّاسِ: اللهُمَّ اشْهَدْ، اللهُمَّ اشْهَد\" ثَلَاثَ مَرَّاتٍ\nيعني رسول الله ﷺ بيوصينا وبيقولنا إن احنا لو تمسكنا بكتاب الله وطبقنا كل إللي فيه عمرنا ما هنضل أبدا\n☆ممكن حد ظريف لطيف يطلع يقولنا:\nأهه النبي نفسه قال تمسكوا بكتاب الله مجبش سيرة السنة\nفاحنا خلاص بقى نعمل بالقرآن ومنعملش بالسنة\nوطبعا الكلام ده باطل، لأن القرآن ربنا قال فيه:\n\"وَأَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ\"\nوقال:\n\"وَمَا آتَاكُمُ الرَّسُولُ فَخُذُوهُ وَمَا نَهَاكُمْ عَنْهُ فَانْتَهُوا\"\nفانت يا أذكى اخواتك لازم تتبع ما جاء به رسول الله ﷺ من أقوال أو أفعال أو تقرير لأن ربنا أمرنا بكده في القرآن إللي انت بتقول عايز تتمسك بيه هو بس\nالمهم بقى رسول الله ﷺ بيقول لهم إن ربنا هيسألهم عن رسول الله ﷺ يوم القيامة هل وصّل الرسالة كاملة لهم، فانتم ساعتها هتقولوا إيه؟\nقالوا نشهد إنك نصحتنا ووصلت لنا الرسالة كاملة، فقال اللهم اشهد\n ثلاث مرات.\nبعد ما أنهى رسول الله ﷺ الخطبة أمر بلال فأذن وبعدين أقام الصلاة،\nوصلى رسول الله ﷺ الظهر ركعتين وبعدها أقام بلال الصلاة مرة تانية وصلى رسول الله ﷺ العصر ركعتين،\nفالسنة للحجاج إنهم يصلوا الظهر والعصر جمع تقديم ويقصروا الصلاة،\nوبعد كده توجه رسول الله ﷺ ومعاه الصحابة لجبل عرفات ووقفوا عليه،\nوجعل رسول الله ﷺ وجهه إلى القبلة، وقال:\n\"وقفتُ هاهنا وعرفة كلها موقف\"\nوقعد يدعو ﷺ ويتضرع إلى الله وهو رافع يديه لحد ما غابت الشمس،\nويجوز للحاج إنه يأكل ويشرب، بل السنة إن يكون مُفطر وليس صائم عشان يقدر يتقوّى على العبادة والذكر والدعاء،\nوالدليل على كده إن أم الفضل زوجة العباس أرسلت زي كوباية كده فيها لبن لرسول الله ﷺ فشربه وهو على ناقته فعرف الناس إنه مش صائم،\nوقال رسول الله ﷺ عن الوقوف بعرفة:\n\" الحج عرفة\"\nيعني الركن الأعظم في الحج هو الوقوف بعرفة، لو واحد عمل كل مناسك الحج ولم يقف بعرفة فكده ملوش حج\nويستمر الوقوف بعرفة لحد فجر يوم النّحْر.\nإيه هو يوم النّحر ده وبيحصل فيه إيه؟\nده إللي هنعرفه 《بكرة》 إن شاء الله \nمصادر جزء النهاردة في التعليقات"}, {"n": 252, "l": "الجزء 226 | حجة الوداع الجزء الرابع | جمرة العقبه", "u": "https://www.facebook.com/groups/710210019782034/permalink/837764237026611/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائتين_وستة_وعشرين\n#أحداث_السنة_العاشرة_من_الهجرة\n#حجة_الوداع_الجزء_الرابع\n#جمرة_العقبة\nاتكلمنا المرة إللي فاتت عن رسول الله ﷺ لما راح وقف على عرفة وقلنا إن زمن الوقوف بعرفة من وقت صلاة ظهر يوم عرفة لحد فجر تاني يوم إللي هو يوم النَّحر،\nفأي حاج وقف على عرفة خلال الفترة الزمنية دي ولو فترة بسيطة يتحسب له الحج، زي ما رسول الله ﷺ قال إن الحج عرفة\nلكن إللي يأتي عرفة في النهار يجب عليه الوقوف لحد غروب الشمس مينفعشي يمشي قبل كده زي ما رسول الله ﷺ عمل\nرسول الله ﷺ استمر واقف بعرفة من بعد زوال الشمس،\nيعني من بعد ما صلى الظهر والعصر جمعا وقصرا؛ لحااااد غروب شمس يوم عرفة،\nأما لو مشي قبل مغرب الشمس فساعتها هيكون عليه فِديَة، يعني عليه ذبح شاة ويفرقها على الفقراء،\nلكن لو مشي قبل المغرب ورجع تاني بالليل ووقف على عرفات هنا يبقى ليس عليه شيء\nولو جاء الحاج للوقوف بعرفة في الليل ممكن يقف فترة زمنية بسيطة وبعدين يمشي ومش هيبقى عليه فدية،\nيبقى باختصار كده الوقوف على عرفة أربع أمور:\n◇الصحيح وإللي عمله رسول الله ﷺ هو: \nالوقوف من بعد الظهر لحد غروب الشمس.\n◇في الليل: \nالوقوف أي فترة زمنية مهما كانت بسيطة تكون صحيحة.\n◇لو وقف في النهار ومشي قبل مغيب الشمس ومجاش تاني وقف بالليل يبقى عليه دم، يعني عليه فِديَة يعني ذبح شاة، وحجه صحيح.\n◇لو وِقف في النهار ومشي قبل مغيب الشمس وجاء مرة تانية في الليل ووقف ولو فترة زمنية بسيطة يبقى كده ليس عليه فِدية وحجه صحيح.\nيارب تكون النقطة دي واضحة\nبعد ما غربت الشمس توجه رسول الله ﷺ لمُزدَلفة إللي هي المشعر الحرام عشان يبيت فيها،\nفالمشروع للحجاج إنهم يفضلوا واقفين في عرفة من بعد صلاة الظهر لحد المغرب،\nوخلال الفترة دي يدعوا ويستغفروا ويلبوا ويذكروا الله،\nومفيش دعاء معين بيوم عرفة، لكن الواحد يدعي باللي هو عايزه،\nأما بالنسبة للذكر، قال رسول الله ﷺ:\n\" خير الدعاء دعاء يوم عرفة، \nوخير ما قلت أنا والنبيون من قبلي:\nلا إله إلا الله وحده لا شريك له له الملك وله الحمد وهو على كل شيء قدير\"\nيعني أفضل الدعاء هو الدعاء في يوم عرفة،\nوأفضل ذكر يُقال في يوم عرفة وقاله رسول الله ﷺ وقالوا الأنبياء من قبله هو لا إله إلا الله وحده لا شريك له......\nفاحنا لازم نكثر من الاستغفار والذكر والدعاء في اليوم ده، قال رسول الله ﷺ:\n\" ما من يوم أكثر عتيقًا من النار من يوم عرفة، وإنه سبحانه ليدنو فيباهي بهم الملائكة\"\nيعني مفيش يوم ربنا ممكن يعتق فيه عدد كبير من النار زي يوم عرفة،\nحتى إنه سبحانه يقترب من عباده اقتراب يليق بجلاله وكماله فيُباهي الله بهم الملائكة،\nالملائكة إللي كانوا قالوا قبل كده لما ربنا قالهم إنه هيخلق خليفة في الارض:\n\"أتجعل فيها من يفسد فيها ويسفك الدماء\"\nفهو هنا سبحانه يتفاخر بعباده المؤمنين أمام الملائكة، إن البشر إللي فيهم سفكوا الدماء كذلك فيهم من يعبدني ويسبح بحمدي زيكم بالضبط\nبعد ما غربت الشمس رجع رسول الله ﷺ لمزدلفة أو المَشْعر الحرام وهي بين عرفة ومِنى ورجع معاه الصحابة، \nوهو ماشي سمع صوت شديد من وراه وزَجْر للإبل بالإسراع،\nيعني عمالين يستعجلوا الإبل بالسّوط عشان يمشوا بسرعة،\nفأمرهم رسول الله ﷺ بالسَّكِينة يعني الهدوء وعدم الإسراع في المشي، قال:\n\"يا أَيُّها الناسُ!\nعليكم بالسكينةِ و الوَقارِ ، فإنَّ البِرَّ ليس في إِيضاعِ الإبلِ\"\nيعني امشوا براحة وبهدوء وخففوا السرعة ومحدش يزاحم حد، فطاعة الله ليست في سرعة السَّير.\nطول الطريق إلى مزدلفة كان رسول الله ﷺ يلبي:\n\"لبيك اللهم لبيك....لبيك لا شريك لك لبيك....إن الحمد والنعمة لك والملك..... لا شريك لك\"\nلما وصل رسول الله ﷺ إلى مزدلفة أمر بالأذان، فأُذّن لصلاة المغرب وأُقيمت الصلاة، \nفصلى المغرب ثلاث ركعات، وبعدين أُقيمت الصلاة مرة تانية فصلى العشاء ركعتين، \nفهو هنا عمل زي ما عمل في صلاة الظهر والعصر في نَمِرَة، جمع صلاة المغرب وصلاة العشاء وصلاهم قصر\nربنا بيقول:\n\"فَإِذَا أَفَضْتُمْ مِنْ عَرَفَاتٍ فَاذْكُرُوا اللَّهَ عِنْدَ الْمَشْعَرِ الْحَرَامِ\"\nيعني بعد ما تمشوا من عرفات؛ تروحوا مزدلفة وتصلّوا هناك المغرب والعشاء، زي ما رسول الله ﷺ عمل.\nسمح رسول الله ﷺ للضعفاء من النساء والشيوخ بإنهم يمشوا من مزدلفة في النصف الأخير من الليل ويتوجهوا لمِنَى، عشان محدش فيهم يتأذى بسبب تزاحم الناس على بعض،\nأما هو وإللي معاه من الأقوياء هيفضلوا في مزدلفة لحد الفجر،\nفهو بعد ما صلى استراح ونام في مزدلفة لحد ما جاء وقت الفجر،\nفقام رسول الله ﷺ وصلى الفجر أبكَر من عادته، يعني هو كان من عادته إنه بيأخر صلاة الفجر شوية،\nلكن المرة دي صلاها بدري عشان يلحقوا يقفوا في المشعر الحرام زي ما وقفوا في عرفة كده،\nيبقى الصحيح إن الحجاج بعد ما يصلوا المغرب والعشاء في مزدلفة إنهم يباتوا فيها ويصلوا فيها الفجر ويقفوا فيها كل واحد في مكانه،\nفهي كلها موقف زي ما عرفة كلها موقف، قال رسول الله ﷺ لما وقف بمزدلفة أو المشعر الحرام:\n\"وقفتُ هاهنا وجَمْع كلها موقف\"\nوجَمْع المقصود بيها المزدلفة، \nفهم هيقفوا ويذكروا الله كثيرا ويدعوا لحد ما النهار يطلع، لكن قبل شروق الشمس،\nفهم لازم يمشوا قبل شروق الشمس ويتوجهوا لمنى؛ لأن العرب في الجاهلية كانوا بيتوجهوا لمنى بعد شروق الشمس،\nفخالفهم رسول الله ﷺ وتوجه لمنى بعد طلوع الفجر وقبل شروق الشمس،\nفالأصل إن الحجاج يعملوا زي رسول الله ﷺ كده،\nإلا الضعفاء من النساء والعجائز الشيوخ والصبيان ومن معهم من محارمهم أو القائمين على شؤونهم،\nدول مفيش مشكلة إنهم يتوجهوا لمنى في النصف الثاني من الليل،\nولو حد مشي من الحجاج الأقوياء قبل طلوع الفجر جائز لكن فاته الأجر العظيم وفاته اتباع سنة رسول الله ﷺ\n☆ملحوظة:\nمزدلفة اتسمت بالاسم ده لأسباب منها: إن الحجاج يقتربون فيها من مِنى،\nفالإزلاف معناه الاقتراب، ربنا بيقول:\n\" وَأُزْلِفَتِ الْجَنَّةُ لِلْمُتَّقِينَ\"\nيعني قُرّبت الجنة للمتقين، والمزدلفة هي المكان إللي بيجمع منه الحجاج الحَصَى لرمي الجَمَرات\nكده احنا بقينا في النَّحر،\nويوم النّحر هو يوم الحج الأكبر، وهو اليوم العاشر من شهر ذي الحجة، أول أيام عيد الأضحى،\nواتسمى يوم الحج الأكبر لأن فيه معظم أعمال الحج زي رمي الجمرات ونَحْر الهَدْي والحَلْق أو التقصير والطواف والسعي لمن كان عليه سعي.\nخرج رسول الله ﷺ وإللي معاه من الصحابة من مزدلفة ومع كل واحد سبع حصيات وتوجهوا لمنى عشان يرموا الجمرات\n☆إيه بقى موضوع رمي الجمرات ده\nشوفوا،\nكلمة رَمْي الجمرات في اللُّغة معناها دَفْع الحصى الصغيرة أو قَذفها، \nيعني إن واحد يمسك طوبة أو حجرة صغيرة ويقوم حادفها،\nتمام كده\nأما بقى معناها عندنا في الشرع إن الحاج ياخد عدد معين من الحجارة الصغيرة ويرميها أو يقذفها في مكان اسمه حَوْض الجمرة،\nوهو مكان معروف في مِنى بيُرمى فيه الحصى إللي بنقول عليه ده،\nوعشان بقى يكون الرمي صحيح لازم الحصى يقع داخل الحوض وتحت العمود الظاهر في وسطها؛\nلأن هو ده إللي عمله رسول الله ﷺ\n☆خلال الأيام الجاية تابعوا من التليفزيون بث مباشر لكل الشعائر دي وهتبقى سهل تفهموها لما تشوفوها إن شاء الله \n◇طيب إيه الحكمة أصلا من موضوع رمي الجمرات ده\nالأصل في تشريع العبادات الانقياد التامّ لربنا عز وجل،\nيعني ننفذ من غير ما نسأل ليه وعشان إيه؛ \nلأن مش كل حاجة احنا عارفين إيه الحكمة من وراها، ممكن تظهر الحكمة وممكن تَخفى،\nبس إللي احنا لازم نكون عارفينه أكيد إن ربنا لا يأمر بشيء إلا وله حكمة فيه ولا يأمر بشيء عبثًا أبدا\nقال مجموعة من أهل العلم إن الحكمة من رمي الجمرات إهانة الشيطان وإذلاله وإرغامه وإظهار مُخالفته؛ \nلأنه عرض لإبراهيم عليه والسلام لما ربنا أراه ذبح ابنه إسماعيل في المنام،\nلكن الكلام ده ليس عليه أي دليل من القرآن أو السنة\nهو اجتهادات واستنتاجات لأهل العلم\nوالحكمة لازم يكون لها دليل واضح،\nومسألة رمي الجمرات مفيش عليها دليل واضح صريح يوضح لنا الحكمة منها،\nفاحنا بنسمع ونطيع ونعمل زي ما رسول الله ﷺ عمل\n☆طيب، رسول الله ﷺ عمل إيه بقى\nتوجه رسول الله ﷺ إلى مِنَى وهو يلبي، لحد ما جاء مكان رمي الجمرة، وكانت الشمس طلعت ودخل وقت الضحى،\nفلما وصل بدأ يرمي الجمرات في الحوض زي ما قلنا،\nوكانوا سبع حصيات في إيده،\nكل واحدة بيرميها يكبر معاها، يعني يرمي واحدة ويقول: \nالله أكبر،\nويرمي التانية ويكبر وهكذا لحد ما السبع حصيات خلصوا،\nوأول ما خلص مشي على طول من مكان رمي الجمرات وموقفش عندها،\nومفيش هنا صلاة عيد للحجاج، رمي الجمرات للحجاج تقوم تقام صلاة العيد، يعني تقدروا تقولوا إنها بدالها\nودي كده اسمها 《جمرة العَقَبة》\nوبيرميها الحُجاج وهم بملابس الإحرام، وقبل التحلل، \nوزمن رمي جمرة العقبة هو من بعد شروق الشمس لحد وقت الظهر وهو الأفضل،\nلكن يجوز الرمي لحد مغيب شمس يوم النّحر\nوفي رمي للجمرات في الثلاث أيام إللي بعد كده وإللي هم أيام التشريق ولهم تفصيل هنعرفه بعدين إن شاء الله \nفاكرين بقى النساء والعجائز إللي كانوا توجهوا لمنى بعد منتصف الليل قبل رسول الله ﷺ \nأهم دول لهم إنهم يرموا جمرة العقبة أول ما يوصلوا،\nأو يبيتوا لحد آخر الليل وبعدين يرموا الجمرات،\nولو أخّروا الرمي لبعد طلوع الشمس برده جائز،\nلكن الأرفق بهم إنهم يرموها في آخر الليل إذا وصلوا مِنى،\nوبعد ما يرموها يرجعوا لمنازلهم في منى للإقامة بها لذبح الهدي ورمي الجِمار في الأيام القادمة ويكملوا مناسك الحج\nبعد ما رسول الله ﷺ رمى جمرة العقبة وقف في منى للناس عشان إللي عايز يسأله،\nفبدأ الناس يسألوه:\nواحد يقوله: \nيا رسول الله! طُفت بالبيت قبل أن أرمي الجمرات، أعمل إيه؟\nوواحد تاني يقول: \nحلقت قبل أن أذبح؟ \nوواحد تالت يقول: \nنَحَرْت قبل أن أرمي؟\nفكل دول كان رسول الله ﷺ يقول لهم:\n\"لا حرج، لا حرج\"\nفده يدل على إن أفعال الحج يوم العيد فيها توسعة،\nوإن الرمي والطواف والسعي والحلق أو التقصير والنحر كلها فيها سِعة من ناحية الترتيب،\nلكن السنة إللي رسول الله ﷺ عمله، وهي إن أول حاجة بدأ بيها هي رمي الجمرات \nوبعد كده يأتي نَحْر الهدي يعني ذبحه وبعدين الحلق أو التقصير وبعدين الطواف والسعي إن كان عليه سعي،\nهو ده الترتيب الصحيح إللي رسول الله ﷺ عمله،\nيبقى بعد رمي الجمرات رسول الله ﷺ راح عشان يذبح الهدي بتاعه \nلكن قبل ما يروح يذبح الهدي خطب رسول الله ﷺ في الناس خطبته الثانية بمنى\nيا ترى رسول الله ﷺ قال إيه في الخطبة الثانية؟\nده إللي هنعرفه كمان شوية إن شاء الله\nمصادر جزء النهاردة في التعليقات"}, {"n": 253, "l": "الجزء 227 | حجة الوداع الجزء الخامس | خطبة المني وأحكام الهَدي", "u": "https://www.facebook.com/groups/710210019782034/permalink/837764720359896/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائتين_وسبعة_وعشرين\n#أحداث_السنة_العاشرة_من_الهجرة\n#حجة_الوداع_الجزء_الخامس\n#خطبة_منى_وأحكام_الهَدي\nاتكلمنا الجزء إللي فات عن رسول الله ﷺ لما رمى الجمرات، ووقفنا عنده لما بدأ يخطب في الناس خطبته الثانية في الحج، وهي خطبته يوم النحر بمنى،\nقال رسول الله ﷺ في الخطبة:\n\"إن الزَّمانُ قَدِ اسْتَدارَ كَهَيْئَةِ يَومَ خَلَقَ السَّمَواتِ والأرْضَ، السَّنَةُ اثْنا عَشَرَ شَهْرًا مِنْها أرْبَعَةٌ حُرُمٌ:\nثَلاثَةٌ مُتَوالِياتٌ: ذُو القَعْدَةِ، وذُو الحِجَّةِ، والمُحَرَّمُ، ورَجَبُ مُضَرَ، الذي بيْنَ جُمادَى وشَعْبانَ....\"\n☆يعني إيه الكلام ده بقى\nفاكريييين في الحلقة الثالثة من السيرة لما اتكلمنا عن أهل النّسِيء\nوقلنا إن أهل النسيء دول كانوا بيعظّموا الكعبة جدا \nوكلمة النسيء معناها التأخير،\nوهم كانت وظيفتهم إنهم يأخروا الأشهر الحرم عن ميعادها، يعني يؤخّروا محرم لصفر مثلا،\nفيبدلوا شهر صفر مع شهر محرم، فيكون ذو القعدة حرام وذو الحجة حرام وبعدين ميجيش شهر محرم،\nلأ، يجي شهر صفر،\nوالأشهر الحرم معناها إن مينفعش يكون فيها حرب والعرب أصلا عيشتهم كانت قائمة على الحرب بينهم،\nففي ثلاثة شهور ورا بعض حُرم:\n《ذو القعدة و ذو الحجة  ومحرم》\nفكده الموضوع عامل لهم أزمة، فأهل النسيء حلّوا لهم المشكلة بالتلاعب في مواقيت الشهور،\nوده تفسير قول ربنا في سورة التوبة:\n\"إِنَّمَا النَّسِيءُ زِيَادَةٌ فِي الْكُفْرِ ۖ يُضَلُّ بِهِ الَّذِينَ كَفَرُوا يُحِلُّونَهُ عَامًا وَيُحَرِّمُونَهُ عَامًا لِّيُوَاطِئُوا عِدَّةَ مَا حَرَّمَ اللَّهُ فَيُحِلُّوا مَا حَرَّمَ اللَّهُ\"\nفرسول الله ﷺ بيقول للناس إن الزمان استدار ورجع لأصله بعد التلاعب إللي كان بيحصل فيه ده،\nفبقى محرم هو محرم، وذو الحجة هو ذو الحجة،\nوأقرّ رسول الله ﷺ الأشهر الحُرُم الأربعة:\nمحرم، ورجب وذو القِعدة وذو الحِجة\nأكمل رسول الله ﷺ الخطبة وقال:\n\"أيُّ شَهْرٍ هذا، قُلْنا: اللَّهُ ورَسولُهُ أعْلَمُ، فَسَكَتَ حتَّى ظَنَنَّا أنَّه سَيُسَمِّيهِ بغيرِ اسْمِهِ،\nقالَ: أليسَ ذُو الحِجَّةِ؟\nقُلْنا: بَلَى، قالَ: فأيُّ بَلَدٍ هذا. قُلْنا: اللَّهُ ورَسولُهُ أعْلَمُ، \nفَسَكَتَ حتَّى ظَنَنَّا أنَّه سَيُسَمِّيهِ بغيرِ اسْمِهِ، \nقالَ: أليسَ البَلْدَةَ.\nقُلْنا: بَلَى، قالَ: فأيُّ يَومٍ هذا؟\nقُلْنا: اللَّهُ ورَسولُهُ أعْلَمُ، فَسَكَتَ حتَّى ظَنَنَّا أنَّه سَيُسَمِّيهِ بغيرِ اسْمِهِ، \nقالَ: أليسَ يَومَ النَّحْرِ؟ قُلْنا: بَلَى.\nقالَ: \nفإنَّ دِماءَكُمْ وأَمْوالَكُمْ، وأَعْراضَكُمْ علَيْكُم حَرامٌ، كَحُرْمَةِ يَومِكُمْ هذا في بَلَدِكُمْ هذا، في شَهْرِكُمْ هذا، \nوسَتَلْقَوْنَ رَبَّكُمْ، فَسَيَسْأَلُكُمْ عن أعْمالِكُمْ...\"\nهنا رسول الله ﷺ بيسأل الصحابة مش لأنه مش عارف، هو بيسألهم عشان يلفت انتباههم لكلامه،\nوالصحابة لما قالوا في كل مرة الله ورسوله أعلم فده كان من أدبهم رضي الله عنهم إنهم ميندفعوش في الإجابة وخصوصا إنهم مكنوش فاهمين الغرض والهدف من السؤال،\nفلما سكت رسول الله ﷺ في كل مرة كانوا مفكرين إنه هيغير أسماء الحاجات إللي سألهم عنها دي،\nلكن هو أقر اسم كل حاجة زي ما هي معروفة، وقال عنِ الشَّهرِ: إنَّه ذو الحِجَّةِ، والبلدُ مَكَّةُ، واليومُ يومُ النَّحْرِ.\nفلما عرّفهم باليوم والمكان والزمن أكّد على معنى كان قاله لهم في خطبة عرفة وهو:\nحرمة الدماء والأموال والأعراض\nفلا يقتل مؤمن مؤمنا بغير حق، ولا يأخذ من ماله بغير رضا منه،\nولا يعتدي على عرض أخيه سواء بزنا أو لواط أو قذف عرضه أو غيره.\nفكل الأمور دي محرمة أشد التحريم، حرام على المسلم أن ينتهكها\nوبيقول انتم هترجعوا لربكم يوم القيامة وهيسألكم عن أعمالكم فاحذروا إنكم تقعوا في شيء من المحرمات إللي قلت لكم عنها دي\nوقال ﷺ:\n\"ألا فلا تَرْجِعُوا بَعْدِي ضُلَّالًا، يَضْرِبُ بَعْضُكُمْ رِقابَ بَعْضٍ...\"\nيعني بيقولهم اوعوا تضلوا بعدي وتُعرِضوا عن إللي تَركتُكم عليه مِنَ التَّمَسُّكِ بِكتابِ ربِّكم وسُنَّةِ نَبيِّكم؛ \nفلو تركتم كتاب الله وسنة نبيكم هتضلوا الطريق وهتقعوا في إللي حذرتكم وهتقتلوا بعض وهو ده الضلال بعينه\nومن الأمور إللي حذر منها رسول الله ﷺ قال:\n\"أَلَا لا يجني جانٍ إلَّا على نفسِهِ ، ولا يجني والدٌ على ولدِهِ ، ولا مَولودٌ على والدِهِ...\"\nيعني محدش يشيل ذنب حد، الشخص المذنب هو بس إللي يتعاقب،\nلأن كان من عادة أهل الجاهلية إنهم يأخذون أقارب الشخص بجنايته،\nيعني لو واحد أخطأ مش بس يعاقبوه هو فقط،\nده يعاقبوه هو وعيلته، وطبعا ده ظلم يؤدي لظلم تاني\nوهنا اختص بذكر الآباء والأبناء إن محدش فيهم يتعاقب بذنب التاني، عشان يعرفهم إن غيرهم أولى بالتحذير،\nيعني الأب مش هيتعاقب بذنب ابنه، ولا الابن هيتعاقب بذنب أبوه ودول أقرب الناس لبعض،\nفمن باب أولى إن محدش تاني من الأقارب يتعاقب بسبب ذنب المخطئ\nوقال ﷺ:\n\"ألا وإنَّ الشَّيطانَ قد أيِسَ أن يُعبَدَ في بلادِكم هذَه أبدًا ولَكن ستكونُ لهُ طاعةٌ فيما تحتقِرونَ من أعمالِكم فسيَرضى بِه..\"\nالمقصود هنا من الشيطان هو إبليس،\nوالمعنى إن إبليس يأس من أن يتبدل دين الإسلام، \nويظهر الإشراك بالله ويستمر، ويرجع الأمر زي ما كان من قبل الإسلام،\n لكن هيبقى في طاعة للشيطان في الأمور إللي الناس بتحتقرها من الذنوب والمعاصي وهي أقل من الكفر،\nزي القتل والنهب وغيرها من الكبائر، وتحقير الصغائر،\nزي ما بيحصل دلوقتي من انتشار الزنا واللواط والسرقة والفجور وسماع الأغاني وغيرها وغيرها من المعاصي والناس شايفة إن دي حرية شخصية\nفرسول الله ﷺ بيقول إن الشيطان هيرضى بالمحتقَر من الذنوب والمعاصي عند الناس،\nلأنه مش هيقدر يحقق الذنب الأكبر وهو إيقاعهم في الكفر الصريح\nقال رسول الله ﷺ في نهاية كلامه:\n\"ألا لِيُبَلِّغِ الشَّاهِدُ الغائِبَ، فَلَعَلَّ بَعْضَ مَن يُبَلَّغُهُ أنْ يَكونَ أوْعَى له مِن بَعْضِ مَن سَمِعَهُ، ثُمَّ قالَ:\nألا هلْ بَلَّغْتُ؟\nألا هلْ بَلَّغْتُ ؟\"\nيعني بيقول الحاضر فيكم يوصل كلامي للغائب إللي مسمعش كلامي، فلعل إللي هيبلغه كلامي هيكون أكثر وعي وفهم من إللي سمعه مني مباشرة.\n☆والكلام ده مش للصحابة بس يا جماعة، كل واحد فينا بيوصلَه كلام رسول الله ﷺ لازم يبلغه للي حواليه،\nانتم بتقرأوا الكلام بسيط وسهل أهه خدوه وانشروه وبلغوه لكل إللي تقدروا عليه،\nربنا مش هيسألنا عن النتيجة، هل فلان عمل باللي انت نصحته بيه ولّا لأ،\nلكن هيسألنا انتم بلغتم إللي نبيكم قال لكم عليه ولّا لأ،\nخليكم فاكرين وصية رسول الله ﷺ:\n\"ألا لِيُبَلِّغِ الشَّاهِدُ الغائِبَ... ألا لِيُبَلِّغِ الشَّاهِدُ الغائِب\"\nومتنسوش إن الوصية دي اتقالت في خطبة الوداع\nيعني دي آخر وصايا رسول الله ﷺ لنا في الموقف المهيب ده وهو ماشي وسط الناس وكل ما يعمل حاجة من مناسك الحج يقول:\n\"خُذُوا مَنَاسِكَكُمْ فَإِنِّي لَا أَدْرِي لَعَلِّي لَا أَحُجُّ بَعْدَ حَجَّتِي هَذِهِ\"\nوفي نهاية الخطبة سألهم هل بلغتكم إللي اتفرض عليّ تبليغه من الرسالة، وهو يقصد من السؤال إن أنا بلغتكم إللي ربنا أمرني بتبليغه لكم فملكوش عذر،\nفلما سألهم مرتين، الناس ردوا عليه وقالوا نعم...نعم.\nبعد ما أنهى رسول الله ﷺ الخطبة توجّه لذبح الهدي\n◇أولا معنى الهدي:\nالهدي يا جماعة زي ما قلنا في الجزء الأول من الرحلة هو:\nالبهيمة من الأنعام سواء إبل أو بقر أو غنم زي الأضحية كده،\nوالحاج عليه هدي واحد فقط، ولو زوّد فله أجر أعلى\n◇ثانيا: حكم الهدي:\nالهدي واجب على الحاج المُتَمَتّع والمُقرِن، يعني إللي بيعملوا حج وعمرة مع بعض، ولكن لو حصل وترك الهدي فحجه صحيح، \nفالهدي واجب وليس ركن من أركان الحج، زي الوقوف بعرفة مثلا.\nأما الحاج المُفرِد فلا يجب عليه هدي، ولكن مُستحَب.\n◇ثالثا: \nحكم إللي ملقاش هدي سواء بسبب عدم وجود الحيوان أو بسبب إن مفيش فلوس فهو عليه صيام عشر أيام، \nيصوم ثلاثة في الحج يكون أخر يوم للصيام هو يوم عرفة،\nولما الحاج يرجع لبلده يصوم السبع أيام\n\" فَمَن لَّمْ يَجِدْ فَصِيَامُ ثَلَاثَةِ أَيَّامٍ فِي الْحَجِّ وَسَبْعَةٍ إِذَا رَجَعْتُمْ تِلْكَ عَشَرَةٌ كَامِلَةٌ\"\nالهدي ده خاص بكل حد من غير أهل مكة، يعني أهل مكة المستطونين مكة ليس عليهم هدي ولا صيام،\nواحنا اتكلمنا عن النقطة دي بالتفصيل في الجزء الأول من رحلة الحج فمش هعيد بقى\n◇رابعا: متى يُذبح الهدي\nالهدي بيُذبح يوم النّحر بعد رمي الجمرات ويستمر زمن النحر لحد نهاية أيام التشريق وهي:\nاليوم الحادي عشر والثاني عشر والثالث عشر من ذي الحجة، يعني أربعة أيامٍ فقط، \nسواء للحاج المتمتع أو الحاج المُقرِن أو الحاج المُفرِد،\nطبعا احنا عارفين إن الحاج المتمتع كان عمل عمرة الأول وبعدين تحلل من العمرة وأحرم للحج يوم التروية زي ما قلنا في الجزء الأول\nأهه المتمتع ده عليه ذبح الهدي في يوم النحر،\nلكن لو ذبح بعد التحلل من العمرة وقبل يوم النحر يبقى ده كله تطوع، ياخد عليه أجر لكن لا يسقط عنه الهدي الواجب إللي هيُذبح يوم النحر\nفكل الصحابة دلوقتي سواء المُقرِن أو المتمتع هيذبحوا الهدي في يوم النحر\n◇خامسا: مكان ذبح الهدي:\nالهدي لازم يُذبح في الحرم، ومِنى كلها حرم زي ما رسول الله ﷺ قال:\n\"نحرت هاهنا ، ومنى كلها منحر ، فانحروا في رحالكم\"\nيعني رسول الله ﷺ بيقولهم مش لازم تيجوا تقفوا في نفس المكان إللي أنا واقف فيه ده عشان تنحروا الهدي،\nمِنى كلها مَنحر، فكل واحد يذبح الهدي بتاعه في مكانه\nفرسول الله ﷺ ذبح الهدي في منى، وهو الأفضل،\nوإذا تم ذبح الهدي في مكة في الحرم يجوز؛\nلأن رسول الله ﷺ قال:\n\"فِجَاج مكة طريق ومنحر\"\nلكن لا يجوز ذبح الهدي خارج الحرم\n◇سادسا: الذبائح تتوزع على مين بقى\nالواجب في لحم الهدي إنه يُوَزّع منه على فقراء الحرم ومساكينه، ويجوز نقل شيء منه لخارج الحرم للأكل والإهداء.\nوهدي المتعة والقِران ده اسمه هدي 《شُكْرَان 》\nفلا يجب أن يُصرف كوووله لمساكين الحرم،\nلكن حكمه حكم الأُضحية،\nيعني يأكل منها ويهدي منها ويتصدق على مساكين وفقراء الحرم، والتصدق على فقرء ومساكين الحرم ده واجب\n◇في نوع تاني من الهدي وهو الهدي إللي بيُذبح بسبب ترك واجب من واجبات الحج،\nفاكرين لما قلنا في الجزء إللي فات إن الحاج لو وقف على عرفة في النهار ومشي قبل مغيب الشمس ومجاش تاني وقف بالليل يبقى عليه فدية يعني عليه ذبح هدي\nأهه ده نوع الهدي إللي بنتكلم عنه،\nفأي حد يترك واجب من واجبات الحج يبقى عليه ذبح هدي،\nالهدي ده لازم يُذبح ويتوزع داخل الحرم، يعني مينفعش توزيعه خارج الحرم\nويدخل مع النوع ده من ناحية وجوب الذبح والتوزيع داخل الحرم؛ الحاج إللي بيقتل صَيد وهو على إحرامه\n◇النوع الثالث والأخير من الهدي، هو الهدي إللي بيُذبح بسبب فعل حاجة من محظورات الإحرام،\nيعني خلال الإحرام مينفعش واحد يقص ضوافره مثلا، فراح قاصصها،\nهنا يبقى عليه ذبح هدي، لكن له الاختيار:\nإما يذبح الهدي ده في المكان إللي عمل فيه المحظور ده، أو يذبحه في أي مكان، سواء برة الحرم أو داخله،\nوله الاختيار برده إنه يوزع لحم الهدي ده سواء في الحرم أو خارج الحرم\nده كده كان أحكام الهدي باختصااار، وإلا فالموضوع يطول شرحه، وفي التعليقات هتلاقوا روابط فيها تفاصيل التفاصيل\nقلنا إن رسول الله ﷺ كان ساق ثلاثة وستين بعير، وجاء علي رضي الله عنه بسبعة وثلاثين بعير من اليمن، فكانوا كلهم مائة،\nرسول الله ﷺ نَحَر بيده الثلاثة وستين بعير، وخلّى علي يذبح السبعة وثلاثين بعير إللي أتى بهم من اليمن،\nقال ابن القيم رحمه الله عن عدد البعير إللي ذبحه رسول الله ﷺ إنه إشارة لعدد سنوات عمر رسول الله ﷺ،\nفهو مات ﷺ وعمره ثلاث وستين سنة،\nيعني بعد حجة الوداع بحوالي ثلاث أشهر ﷺ \nبعد ما رسول الله ﷺ نحر الهدي، حلق شعر رأسه، وبكده حصل التحلل الأول من الإحرام\nعمل إيه تاني رسول الله ﷺ بعد ما تحلل التحلل الأول من الإحرام؟\nده إللي هنعرفه بكرة إن شاء الله، وهيبقى آخر جزء قبل أجازة عيد الأضحى كل سنة وانتم طيبين وبخير وعافية في الدين والدنيا \nمصادر جزء النهاردة في التعليقات"}, {"n": 254, "l": "الجزء 228 | حجة الوداع الجزء السادس والاخير | ايام التشريق", "u": "https://www.facebook.com/groups/710210019782034/permalink/837765047026530/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائتين_وثمانية_وعشرين\n#أحداث_السنة_العاشرة_من_الهجرة\n#حجة_الوداع_الجزء_السادس_والأخير\n#أيام_التشريق\nقبل ما نتكلم في جزء النهاردة في نقطة عايز أقولها المفروض كنت قلتها في الحلقة بتاعة يوم عرفة،\nبس نسيت أقولها لكم من كتر لخبطة المعلومات في دماغي وأنا بكتب معلش\nالنقطة دي هي نزول آية:\n\" الْيَوْمَ أَكْمَلْتُ لَكُمْ دِينَكُمْ وَأَتْمَمْتُ عَلَيْكُمْ نِعْمَتِي وَرَضِيتُ لَكُمُ الْإِسْلَامَ دِينًا\"\nالآية دي نزلت على رسول الله ﷺ في يوم عرفة وهو على الناقة بتاعته، \nفلما نزل عليه الوحي بركت الناقة في الأرض من شدة ثِقَل الوحي،\nوالآية معناها إن بعد ما رسول الله ﷺ حج؛ كده اكتمل دين الإسلام بأركانه كلها،\nالشهادتين والصلاة والصيام والزكاة والحج، وبعد الآية دي لم ينزل بعدها حلال أو حرام،\nنزلت آيات تانية، لكن الحلال والحرام كله كان نزل قبل الآية دي\nويُروى إن عمر بن الخطاب رضي الله عنه لما سمع الآية بكى، فسأله رسول الله ﷺ عن سبب بكائه قال عمر:\n\"أبكاني أنّا كنا في زيادة من ديننا، فأما إذا أُكمِل فإنه لم يَكمُل شيء إلا نَقُص\"\nيعني احنا كنا في البداية مجموعة بسيطة وزادت على مر السنين لحد ما انتشر وظهر،\nوبعد كده سيلحقه النقص والإخلال حتى لا يبقى فيه إلا آحاد وقِلة أيضًا كما بدأ،\nوإللي بيؤيد معنى كلام عمر قول رسول الله ﷺ:\n\"إن الإسلام بدأ غَرِيبًا، وسيعود غريبا، فَطُوبَى للغُرَبَاء\"\nفلما سمعه رسول الله ﷺ قال له:\nصدقت\nيعني فعلا هو ده إللي هيحصل، \nوشوفوا كده الدنيا حوالينا عاملة إزاي وشوفوا كمية الناس المفرّطة في اتباع الدين والقلة القليلة إللي متمسكة باللي كان عليه رسول الله ﷺ والصحابة،\nوالناس شايفاهم إنهم حاجة غريبة وبيحاربوهم زي ما كان رسول الله ﷺ والصحابة بيُحاربوا\nوبمناسبة الآية دي كان في واحد من اليهود بيقول لعمر بن الخطاب رضي الله عنه انتم نزلت عليكم آية لو كانت نزلت علينا احنا اليهود كنا عملنا اليوم إللي نزلت فيه ده عيد،\nفسأله عمر عن الآية فقال له اليهودي إنها إكمال الدين إللي قلنا عليها دي\nندخل بقى في جزء النهاردة \nاتكلمنا المرة إللي فاتت عن رسول الله ﷺ لما رمى جمرة العقبة وبعدين ذبح الهدي،\nتالت حاجة عملها رسول الله ﷺ في يوم النحر هو إنه حلق شعره كله لحد ما وصل للعظمتين إللي عند الأذن وفصل بين اللحية وشعر الرأس، هنا كده\nلو حطيتم إيدكم في المنطقة دي كده هتحسوا بالعظمتين، فالسنة هي الحلق لحد ما يبلغ العظمتين دول،\nطبعا مفيش حلق لحية، لأن حلقة اللحية حرام\nفهو حلق شعر رأسه فقط\nويجوز تقصير الشعر بدل الحلق، لكن الأفضل هو الحلق زي  ما رسول الله ﷺ عمل\nوده كده اسمه التحلل الأول، \nوالتحلل الأول ده يجوز فيه عمل كل محظورات الإحرام إلا جماع النساء\nبعد ما رسول الله ﷺ حلق، طيّبته السيدة عائشة، يعني وضعت له مسك، وبعد كده ركب الناقة وتوجه للبيت الحرام عشان يطوف به طواف الإِفاضة.\n☆يعني إيه طواف الإِفَاضَة\nكلمة إفاضة نفسها معناها في اللغة:\nالزَّحْفُ والدَّفْعُ في السَّيرِ بكثرةٍ، يعني ناس كتير جدا يمشوا مع بعض، زي كده سِيل من البشر بيتحرك في اتجاه واحد\nعشان كده طواف الإفاضة اتسمى بالاسم ده،\nلأن الناس بتفيض من مِنَى إلى مكة، وطواف الإفاضة ده ركن من أركان الحج زي الوقوف بعرفة كده لا يصح الحج بدون طواف الإفاضة\nولازم طواف الإفاضة يكون بعد الوقوف بعرفة، \nيعني لو واحد طاف طواف الإفاضة قبل الوقوف بعرفة لا يسقط من عليه فرض الطواف بعد الوقوف بعرفة \nولو واحد أخّر طواف الإفاضة لبعد يوم النّحر إللي هو يوم العيد وطاف في أيام التشريق فده جائز من غير ما يكون عليه فِديَة\nوالطواف يكون سبعة أشواط يبدأ كل شوط من أمام الحجر الأسود ويخلي الكعبة على يساره وهو بيطوف،\nيعني بيطوف عكس اتجاه عقارب الساعة\nبعد ما أنهى رسول الله ﷺ الطواف أتى بني عبد المطلب وهم يسقون الحجيج من زمزم،\nلأنهم هم المسؤولين عن سقاية الحجيج؛ لأن عبد المطلب هو إللي حفر زمزم،\nفقال لهم رسول الله ﷺ:\n\"انْزِعُوا، بَنِي عبدِ المُطَّلِبِ، فَلَوْلَا أَنْ يَغْلِبَكُمُ النَّاسُ علَى سِقَايَتِكُمْ لَنَزَعْتُ معكُمْ\"\nيعني اسقوا يا بني عبد المطلب، لولا خوفي إن الناس تفكّر إن السقاية من مناسك الحج ويزدحموا عليه ويغلبوكم على السقاية لكنت سقيت معكم،\nوفضل السقاية عالي عشان كده رسول الله ﷺ كان عايز يشارك فيه،\nفلما قالهم كده أعطوه دَلْو فيه ماء زمزم فشرب لحد ما امتلأ منه ﷺ.\nاحنا قلنا إن من أعمال الحج يوم النحر السعي بين الصفا والمروة للذي عليه سعي،\nهنا رسول الله ﷺ ليس عليه سعي بين الصفا والمروة،\n لأنه كان مُقرِن وخلاص سعى في الأول خالص لما دخل مكة،\nفالحاج المُقرن والمُفرِد عليه سعي واحد فقط،\nإما يسعى بعد ما يأتي لمكة ويطوف طواف القدوم، إللي هو الطواف إللي بيطوفه الحاج أو المعتمر أول ما يدخل مكة زي ما رسول الله ﷺ عمل وهو الأكمل،\nأو ممكن يأخّره لبعد طواف الإفاضة، يعني يطوف طواف الإفاضة ويسعى بين الصفا والمرة،\nأما بقى الحاج المتمتع فعليه سعيين\nالأول بتاع العمرة بعد طواف القدوم وقبل ما يتحلل من العمرة،\nوالسعي التاني في يوم النحر بعد طواف الإفاضة،\nوطبعا احنا اتكلمنا بالتفصيل عن السعي بين الصفا والمروة في الجزء الثاني من الرحلة فمش هعيد \nبعد ما رسول الله ﷺ طاف طواف الإفاضة زي ما شرحنا كده، صلى الظهر في مكة في أول وقته مع الصحابة،\nوبعدين رجع لمِنى فلقى باقي الصحابة مستنيِينه عشان يصلي بيهم الظهر،\nفصلى رسول الله ﷺ معاهم مرة تانية الظهر في آخر الوقت،\nفبقت كده الصلاة التانية بالنسبة له هو نافلة، وبالنسبة للموجودين في مِنى صلاة فريضة\nوبكده يبقى خلصت أعمال الحج في يوم النّحر يوم الحج الأكبر إللي قال عنه رسول الله ﷺ:\n\"إن أعظم الأيام عند الله يوم النحر\"\nوقال:\n\"يوم عرفة ويوم النّحر وأيام التَّشريق عيدُنا أهل الإسلام وهي أيام أكل وشرب وذكرٍ لله عز وجل\"\nوالمقصود إن الأكل والشُّرب في أيام الأعياد يُستعان بها على ذكر الله تعالى وطاعته وده من تمام شكر النعمة،\nيعني إن العبد يستعين بالنعمة إللي ربنا أعطهاله على أداء الطاعات\nفالمشروع في الأيام دي كثرة ذكر الله بالحمد والتهليل والتكبير\n☆إيه بقى موضوع أيام التشريق ده\nأيام التشريق هي:\nالثلاثة أيام التي تأتي وراء يوم النحر وهي أيام:\nالحادي عشر، والثاني عشر، والثالث عشر من شهر ذي الحجة، \nوالأيام دي لا يجوز فيها الصيام، فهي أيام أكل وشرب وذكر لله تعالى زي ما رسول الله ﷺ قال،\nإللي له رخصة يصوم فيها هو الحاج القارن والمتمتع إللي لم يجد هدي،\nاحنا قلنا إن لو الحاج ملقاش هدي يصوم ثلاثة أيام في الحج آخرهم يوم عرفة وسبعة لما يرجع من الحج،\nرسول الله ﷺ رخّص للي ملقاش هدي ومصمش قبل يوم النحر إنه يصوم أيام التشريق،\nأما غير كده فلا يجوز صوم أيام التشريق الثلاثة\nوكان رسول الله ﷺ أمر سعد بن أبي وقاص إنه ينادي في الناس في منى:\n\"إِنَّهَا أَيَّامُ أَكْلٍ وَشُرْبٍ، فَلا صَوْمَ فِيهَا\"\nحتى لو إللي عايز يصوم فيها قضاء رمضان لا يجوز على الصحيح من أقوال العلماء.\n◇أيام التشريق اتسمت بالاسم ده لسببين على اختلاف الأراء، \n¤الأول:\nإنهم كانوا يُشَرِّقون فيها لحوم الأضاحي، \nيعني يقطعوا لحم الأضحية قطع صغيرة ويعرّضوها للشمس عشان الرطوبة إللي فيها تطلع وبكده اللحم يحافظ على نفسه ولا يفسد،\nفهي طريقة لحفظ اللحم لأن مكنش عندهم تلاجات\n¤السبب الثاني:\nلأن صلاة العيد إنما تُصلى بعد أن تشرق الشمس، فسُمّيت الأيام كلها بأيام التشريق تبعاً لليوم الأول: يوم العيد، \nوهذا من باب تسمية الشيء باسم بعضه، وهو مشهور ومعروف في اللغة.\nوخلال أيام التشريق دي قعد رسول الله ﷺ في منى وبات ليالي أيام التشريق في منى،\nفالأصل إن الحجاج يقعدوا في منى ويبيتوا فيها،\nيعني هيباتوا في منى ليلة الحادي عشر والثاني عشر والثالث عشر من ذي الحجة،\nوخلال الثلاث أيام دي كان رسول الله ﷺ يخرج لرمي الجمرات في حوض الجمرة إللي قلنا عليه قبل كده،\nلكن رمي الجمرات هنا مختلف، \nالرمي في ثلاث أيام التشريق بيكون بعد الزوال يعني بعد الظهر لحد غروب الشمس،\nبعكس جمرة العقبة إللي كانت وقت الضحى لحد غروب الشمس،\nورمي الجمرات في أيام التشريق بيكون عدد الحصا فيها واحد وعشرين، بعكس جمرة العقبة إللي كان عدد الحصى فيها سبعة\nيبقى مجموع الحصا كله في رمي الجمرات سبعين حصاة،\nسبعة في يوم النحر، وواحد وعشرين في كل يوم من أيام التشريق، يبقى مجموعهم سبعين\nورمي الجمرات في أيام التشريق بيكون في ثلاث أماكن مختلفة، \nالمكان الأول هو الأقرب إلى مسجد الخِيف،\nوفيه تُرمى الجَمرة الأولى وهي سبع حصيات في حوض الجمرة ومع كل حصى يُكبّر الحاج ويدعو، واسمها الجمرة الصُّغرى، \nالمكان الثاني هو أقرب إلى جمرة العقبة إللي حصل فيها رمي جمرات يوم النحر،\nوتكون برده سبع حصيات مع كل مرة يكبّر الحاج ويدعو، واسمها الجمرة الوُسطى،\nأما الجمرة الكبرى فتكون في نفس المكان إللى رمى فيه رسول الله ﷺ رمية العقبة في يوم النحر،\nوهي برده سبع حصيات، مع كل مرة يرمي فيها يكبّر فقط،\nهنا مفيش دعاء،\nفأول ما يخلص الرمي يمشي من المكان مباشرة، بعكس الصغرى والوسطى هيرمي ويدعو\nطبعا الأماكن إللي قلنا عليها دي عندها علامات دلوقتي وتوجيهات، يعني إللي هيروح الحج هيعرف يوصل للأماكن إللي بنتكلم عنها دي\nوانتم ممكن تتابعوا من التليفزيون أحداث الحج هتشوفوا كل إللي اتكلمنا عنه ده\nكل إللي قلناه ده رسول الله ﷺ عمله في أيام التشريق الثلاث، كل يوم يخرج ويكرر نفس الموضوع.\n◇في حاجة اسمها التَّعَجُّل في يومين، ربنا بيقول:\n\"فَمَنْ تَعَجَّلَ فِي يَوْمَيْنِ فَلا إِثْمَ عَلَيْهِ وَمَنْ تَأَخَّرَ فَلا إِثْمَ عَلَيْهِ\"\nوده معناه إن الحاج يجوز له إن يخرج من منى ويُنهي مناسك الحج في ثاني أيام التشريق إللي هو الثاني عشر من ذي الحجة،\nفيخرج من منى بعد رمي الجمرات ويتوجه لمكة ويطوف طواف الودع وهو سبعة أشواط زي ما شرحنا، وليس عليه سعي بين الصفا والمروة، \nيطوف بس، وبعدها يصلي ركعتين ويمشي بقى يرجع بلده ويبقى كده خلاص حجه خلص\nلكن كل ده بشرط إنه يخرج من مِنى قبل غروب شمس ثاني أيام التشريق،\nلأن لو غربت شمس ثاني يوم أيام التشريق وهو لسه موجود في منى؛ يبقى لازم يبيت في منى ويرمي جمرة ثالث أيام التشريق\nيبقى لو مشي قبل المغرب مفيش مشكلة وليس عليه أي ذنب ولا أي شيء،\nلكن لو دخل عليه المغرب بقى لازم عليه المبيت ورمي الجمرات في اليوم الثالث\nرسول الله ﷺ بقى قعد في منى لحد آخر يوم من أيام التشريق ورمى فيها الجمرات، وبعدين طلع على مكة طاف طواف الوداع وخرج من مكة،\nولازم آخر حاجة يعملها الحاج في مكة هي طواف الوداع، \nيعني لو حب مثلا يقعد فترة بعد أيام التشريق مفيش مشكلة، لكن هيأجل طواف الوداع لحد الخروج من مكة والرجوع لبلده،\nيعني قبل ما يرجع لأهله مباشرة يطوف طواف الوداع،\nيكون آخر عهده بالبيت هو طواف الوداع زي ما قال رسول الله ﷺ:\n\"لا ينفِرنَّ أحدٌ منكم حتَّى يكونَ آخرَ عهدِه الطَّوافُ بالبيتِ\"\nيعني محدش يخرج من مكة إلا لما يكون آخِر مَناسِكِه الطواف بالبيت، إللي هو طواف الوداع\n☆طبعا أهل مكة المقيمين مش محتاجين طواف وداع لأنهم قاعدين فيها أصلا\nآخر خطبة خطبها رسول الله ﷺ في الحج كانت ثاني أيام التشريق،\nوفيها أكد رسول الله ﷺ على حرمة الاعتداء على دماء وأموال وأعراض المسلمين للمرة الثالثة، \nوللأسف إللي يشوف واقع المسلمين مش هقول من بعد رسول الله ﷺ، لأ، في واقعنا دلوقتي هتلاقوا إن كل إللي حذر منه رسول الله ﷺ وقع،\nواعتداء المسلمين على بعض سواء بأخذ أموال أو الكلام في الأعراض وحتى القتل بقى حاجة سهلة للأسف ومحدش بيهتم ولا بيتبع وصية رسول الله ﷺ \nربنا يعصمنا وإياكم من الزَّلل\nدي كده كانت حجة الوداع باختصاااار من غير الدخول في تفريعات فقهية كتير،\nاحنا مشينا مع رسول الله ﷺ في خطوط عريضة عشان نعرف هو عمل إيه،\nوشوفنا الوصايا بتاعته في حجة الوداع، \nوكان الصحابة في حجة الوداع بيتحدثوا عن حجة الوداع وبيتناقلوا كلمة《حجة الوداع》 لكن مكنوش فاهمين معناها،\nعبد الله بن عمر بيقول:\n\"كنا نَتَحَدَّثُ بحَجَّةِ الوَداعِ، والنبيُّ ﷺ بيْنَ أظْهُرِنا، ولا نَدْرِي ما حَجَّةُ الوَداعِ\"\nيعني هم سمعوا رسول الله ﷺ بيقول الكلمة دي، فتناقلها الناس وهم مش فاهمين يعني إيه حجة الوداع،\nفلما مات رسول الله ﷺ بعد الموقف ده بثلاثة أشهر تقريبا عرفوا إن رسول الله ﷺ كان بيودعهم وبيقول لهم آخر وصاياه\nبعد ما أنهى رسول الله ﷺ طواف الوداع خرج هو والصحابة إللي معاه من مكة ونزلوا مكان اسمه الأبطح،\nومنه أرسل عائشة وأخوها عبد الرحمن لمكة عشان عائشة تعمل عمرة زي ما قلنا قبل كده،\nبعد ما السيدة عائشة رجعت انطلقوا كلهم راجعين للمدينة.\nحصلت أحداث في طريق الرجوع من مكة إلى المدينة،\nهنتكلم عنها بعد العيد إن شاء الله \n♡اتفرجوا بقى على مناسك الحج من التليفزيون وافتكروا رسول الله ﷺ وعيشوا معاه اللحظة\n \nوادعوا إن ربنا يرزقنا حج بيته وزيارة مسجد نبيه في يوم من الأيام ويحشرنا معاه ومع الصحابة ويجمعنا بيهم في الفردوس الأعلى،\nنتمنى على الله إنه لا يحرمنا وإياكم جميعا من الفضل ده يارب \n♡أخيرا يا جماعة أنا بشر،\nحاولت أجتهد إني أنقل لكم المعلومة الصحيحة وأبسّط المعلومة على أد ما أقدر،\nفما كان من خير فمن توفيق الله وحده،\nولو كان في خطأ أو نسيان فمني ومن الشيطان والله ورسوله منه بَراء،\nوطبعا انتم عارفين:\nأي ملاحظة ياريت تقوليلي، فكما قال رسول الله ﷺ:\n\"المؤمِنُ مرآةُ أخيهِ\" \nكل عام أنتم بخير وعافية في الدين والدنيا"}, {"n": 255, "l": "الجزء 229 | احداث السنه العاشره من الهجرة | غدير  خم", "u": "https://www.facebook.com/groups/710210019782034/permalink/837765470359821/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائتين_وتسعة_وعشرين\n#أحداث_السنة_العاشرة_من_الهجرة\n#غَدِير_خُمْ\nاتكلمنا في الأجزاء إللي فاتت عن صفة حج رسول الله ﷺ،\nوقلنا إن رسول الله ﷺ حج مرة واحدة فقط،\nوالحجة دي اسمها حجة الوداع،\nبعد ما رسول الله ﷺ أنهى حجة الوداع توجه ناحية المدينة،\nفي الطريق حصلت أحداث، \nمن الأحداث إللي حصلت الموقف إللي حصل بين صفية بنت حُيَي زوجة رسول الله ﷺ وبين رسول الله ﷺ نفسه وبين زينب بنت جحش لما كانت السيدة صفية راكبة على جمل بطيء واتأخرت عنهم في المشي واستقبلها رسول الله ﷺ وهي بتبكي وتقول له: \nانت خلتني أركب على جمل بطيء واتأخرت عنكم، فرسول الله ﷺ قعد يمسح دموعها ويهديها ويسكّتها، لكن هي صممّت على البكاء وزادت فيه، \nفرسول الله ﷺ غضب وسابها ومشي، وحصلت باقي القصة إللي اتكلمنا عنها في الجزء المائة وثمانية وأربعون واحنا بنتكلم عن تعامل رسول الله ﷺ مع أخطاء زوجاته، ممكن ترجعولها لو حابين تفتكروا الأحداث\nمن الأحداث إللي حصلت كمان في طريق العودة من مكة للمدينة أحداث غَدِيرُ خُمْ،\nكلمة غدير معناها الماء إللي بيمشي في الوادي، وكلمة خم اسم لمكان بين مكة والمدينة،\nفالمكان إللي اسمه خُم ده كان فيه مياه فاتسمى غدير خم، يعني مياه خم، وهو في نص المسافة تقريبا بين مكة والمدينة، في مكان قريب من منطقة الجُحْفَة\nوكان اليوم ده هو اليوم الثامن عشر من ذي الحجة،\nكان رسول الله ﷺ نزل في المكان ده مع الصحابة وقعدوا فيه،\nزي كده محطة استراحة قبل ما يكملوا الطريق،\nلأن الطريق من مكة للمدينة بياخد حوالي ثمانية أيام مشي،\nنادى رسول الله ﷺ في الصحابة:\nالصلاة جامعة.\nوالكلمة دي كانت معروفة عند الصحابة إنها لما بتتقال يبقى في حاجة مهمة رسول الله ﷺ عايز يقولها لهم\nفلما اجتمع الصحابة خطب فيهم رسول الله ﷺ خطبة، فَحَمِدَ اللَّهَ وَأَثْنَى عليه، وَوَعَظَ وَذَكَّرَ،\nيعني رسول الله ﷺ وصف الله بصفات الكمال وأثنى عليه بتنزيهه عَن كل ما لا يَليقُ به،\nووعظ وذكر معناها إن رسول الله ﷺ أمر بِالطَّاعةِ ووصَّى بها، وذكَّرَ الصحابة بِما قد غَفلُوا عنه بسبب مزاولةِ الأهلِ والعيالِ وهو أداء حق العبودية كاملة لله عز وجل.\n☆عارفين كده زي ما المشايخ بيخطبوا الخطب أو يقولوا دروس، بيبقى في مقدمة للدرس أو الخطبة فيها الحمد والثناء على الله وتذكير الناس بصفة عامة بتقوى الله،\nأهه كان كلام رسول الله ﷺ حاجة شبيهة بكده\nالمهم، رسول الله ﷺ هنا هينبه الناس للكلام إللي هيقوله\nقال رسول الله ﷺ بعد المقدمة دي:\n\"أَمَّا بَعْدُ، أَلَا أَيُّهَا النَّاسُ فَإِنَّمَا أَنَا بَشَرٌ يُوشِكُ أَنْ يَأْتِيَ رَسُولُ رَبِّي فَأُجِيبَ،\nوَأَنَا تَارِكٌ فِيكُمْ ثَقَلَيْنِ:\nأَوَّلُهُمَا كِتَابُ اللهِ فِيهِ الْهُدَى وَالنُّورُ فَخُذُوا بِكِتَابِ اللهِ، وَاسْتَمْسِكُوا بِهِ، فَحَثَّ عَلَى كِتَابِ اللهِ وَرَغَّبَ فِيهِ،\nثُمَّ قَالَ: \nوَأَهْلُ بَيْتِي، أُذَكِّرُكُمُ اللهَ فِي أَهْلِ بَيْتِي، أُذَكِّرُكُمُ اللهَ فِي أَهْلِ بَيْتِي، أُذَكِّرُكُمُ اللهَ فِي أَهْلِ بَيْتِي\"\nيعني يا جماعة أنا بشر، ومعنى إني بشر فأنا هموت، وموعد موتي قرب خلاص،\nفدلوقتي ده واحد قرب يموت فبيوصي وصية، والطبيعي إن الناس تنتبه للشخص إللي بيوصي وصية في آخر عمره،\nوده كان من ضمن التمهيد منه ﷺ للصحابة عشان يهوّن عليهم صدمة موته،\nلأن موت رسول الله ﷺ هو أعظم المصائب على الإطلاق، ومهما حاولنا نتخيل مشاعر الصحابة لما رسول الله ﷺ مات مش هنقدر\nدول ناس عاشوا مع رسول الله ﷺ كل لحظة بحلوَها ومُرّها وكانوا بيحبوه أكثر من نفسهم،\nفرحمة بيهم كان في تمهيد وإشارات إن رسول الله ﷺ هييجي عليه يوم من الأيام ويموت زي ما ربنا قال في القرآن:\n\"إِنَّكَ مَيِّتٌ وَإِنَّهُم مَّيِّتُونَ\"\nوكمان لما كان بيقولهم في حجة الوداع إنه ممكن ميقابلهمش بعد العام ده،\nوكان جبريل عليه السلام كل سنة بيراجع القرآن مع رسول الله ﷺ مرة واحدة في رمضان إلا السنة دي، السنة العاشرة من الهجرة، راجعه القرآن مرتين، وهو أخبر الصحابة بالموضوع ده ﷺ،\nوكل ده والصحابة لسه مش مستوعبين إللي بيحصل، فهو هنا بيذكرهم ويمهد لهم تاني إنه بشر وزيه زي أي بشر هيجيله ملك الموت ليقبض روحه\nبعد ما رسول الله ﷺ وضّح لهم حقيقة إنه خلاص وقت موته قرّب وصّاهم بالتمسك بكتاب الله، \nوقال ثَقَلَيْنِ ومفردها ثَقَل والكلمة دي تُقال للشيء العظيم النفيس،\nيعني كتاب الله شيء عظيم نفيس فيه الهداية والنور،\nفقال لهم يتمسّكوا ويعتصموا بيه بقوة؛\nلأنه هو السبب إللي بيوصل الناس إلى رِضى الله ورحمتِه،\nوهو نورُه الَّذي يَهدي به مَنِ اتَّبعَه إلى الهدَى والرَّشادِ، \nوإللي يترك التمسك بالقرآن واتباعه كان على ضلالةٍ، يعني على هلاكٍ وضَياعٍ مِن أمْرِه\nقال تعالى:\n\"إِنَّ هَذَا الْقُرْآنَ يِهْدِي لِلَّتِي هِيَ أَقْوَمُ\"\nتاني أمر رسول الله ﷺ قال لهم يراعوه ويراعوا حرمته هم أهل بيته ﷺ،\nوالمقصود من وصية رسول الله ﷺ إن الصحابة يراعوا أهل بيته ويحبوهم ويتجنبوا كل شيء يُسيء لهم،\nويبعدوا عن أذيتهم ويمتنعوا عن ظلمهم وإنهم يعطوهم حقوقهم كاملة، \nوليس المقصود وجوب اتباعهم زي ما طائفة الشيعة بيقولوا\nلأ، وصية رسول الله ﷺ كانت من أجل احترامهم وتوقيرهم وعدم التعرض بسبّهم وأذاهم ،\nومش معنى كده كمان إنه بيقدمهم على غيرهم ممّن هو أفضل منهم زي أبي بكر وعمر وعثمان رضي الله عنهم أجمعين\nوأهل بيت النبي ﷺ المقصود بيهم هنا في الحديث إللي هم يَحرُم عليهم الصدقة وهم:\nآل علي ، وآل عقيل ، وآل جعفر ، وآل عباس،\nوفي معاني تانية لأهل البيت،\nيعني عندنا مثلا في حادثة وفد نجران لما رسول الله ﷺ جاء بعلي وفاطمة والحسن والحسين عشان المُباهلة وقال اللهم هؤلاء أهلي،\nفده أضيق معنى لأهل البيت، المعنى الثاني بيدخل فيه نساء النبي ﷺ، زي ما في آيات سورة الأحزاب،\nفكده يبقى عندنا ثلاث معاني لأهل البيت، كل معنى بيكون على حسب السياق إللي جاء فيه،\nفالمقصود من كلمة أهل بيتي في الحديث بتاعنا النهاردة هم الأقارب من جهة الأصل إللي يَحرُم عليهم أكل الصدقة سواء كانت زكاة أو نذر أو كفارة\n☆خدوا بالكم مش معنى كده إن الناس تؤذي وتظلم باقي أهل النبي ﷺ لأنه متكلمش عنهم في الحديث\nفي مواقف تانية اتكلم رسول الله ﷺ عن مكانة أمهات المؤمنين وجاء فضلهن في القرآن،\nفهن من أهل بيت رسول الله ﷺ \nفالشاهد من الكلام إن رسول الله ﷺ ذكّر الناس وحَثّهم على الإحسان لأهل بيته ﷺ،\nوكان أبو بكر الصديق رضي الله عنه بيقول لعلي رضي الله عنه  بعد موت رسول الله ﷺ:\n\"والذي نفسي بيدِه لَقرابةُ رسول الله ﷺ أحبُّ إليَّ أنْ أَصِلَ من قرابَتِي \" .\nيعني إنه يصل قرابة رسول الله ﷺ بالإحسان إليهم ومنهم علي أحب إليه من إنه يصل قرابته هو رضي الله عنه.\nلما كان رسول الله ﷺ واقف بيخطب في الصحابة في غدير خُم أخذ بيد علي رضي الله عنه وقال:\n ألستُ أَوْلى بالمؤمنين من أنفسِهم؟!\n قالوا: بلى.\n قال رسول الله ﷺ:\n ألستُ أَوْلى بكلِّ مؤمنٍ من نفسِه؟!\n قالوا: بلى.\n قال: فهذا وليُّ مَن أنا مولاه، اللَّهمَّ والِ من وَالاهُ، اللهمَّ عادِ من عاداهُ\"\nرسول الله ﷺ هنا بيسأل الصحابة سؤال تقريري، \nيعني بيقول لهم مش أنا أحَقَّ الناس بالمحبَّةِ والتَّوقيرِ والإخلاصِ بمَنزِلةِ الأبِ للأولادِ؟! \nزي كده لما نقول لحد هو انت مش عارف إن الشمس بتطلع كل يوم الصبح،\nفكان رد الصحابة بالإيجاب، يعني أيوة عارفين إنك يا رسول الله أوْلى بالمؤمنين من أنفسهم \n☆ثواني كده، \nيعني إيه أصلا جملة: ألستُ أَوْلى بالمؤمنين من أنفسِهم \nشوفوا كده لما نقول ده فلان كان 《أَوْلى》 الناس إنه يدافع عن أخوه،\nمعنى كلمة أولى هنا هي إن فلان هو الأَحقّ والأَقرب إنه يدافع عن أخوه،\nفرسول الله ﷺ بيقول إنه أحق وأقرب إنه يحكم لكل مؤمن في خاصة نفسه،\nيعني مثلا لو واحد اختار لنفسه حاجة معينة شايف فيها مصلحته، وبعدين رسول الله ﷺ قال على الحاجة دي لأ أو بلاش، فهنا يجب سماع أمر رسول الله ﷺ لأن رسول الله ﷺ هو أكتر واحد تهمه مصلحة المؤمنين حتى أكثر من أنفسهم\nفهو ﷺ أحق الناس بالحكم فيهم من أنفسهم.\nوبعد كده رسول الله ﷺ أكّد على الكلام، وقال:\n ألَستُ أَوْلى بكلِّ مؤمنٍ مِن نفْسِه؟!\"\nفأقر الصحابة كلام رسول الله ﷺ للمرة التانية، فهنا بقى رسول الله ﷺ وضّح مكانة علي رضي الله عنه وإن رسول الله ﷺ بيحب علي، فلازم المؤمنين يحبوه لأن رسول الله ﷺ بيحبه،\nودعا رسول الله ﷺ إن ربنا يحب كل إللي يحب علي، ويُعادي كل مَن يعادي  علي رضي الله عنه،\nوالموضوع كله بيتكلم عن مكانة علي رضي الله عنه وإن هو من أهل بيته ﷺ،\nوالموضوع ملوش أي علاقة نهائي بإن رسول الله ﷺ بيوصي بالخلافة لعلي من بعده ﷺ\nولو كان الموضوع عن الخلافة كان رسول الله ﷺ قالها صراحة كده\nده بالعكس بقى، \nكلام رسول الله ﷺ إللي قاله ده كان له دافع وقصة من وراه\nفاكرين لما قلنا في الجزء المئتين وثمانية عشر إن رسول الله ﷺ أرسل خالد بن الوليد لقبيلة همدَان في اليمن يدعوهم إلى الإسلام فلم يستجيبوا له، \nفأرسل بعدها علي بن أبي طالب رضي الله عنه بدل خالد وقال له يقول لخالد يرجع للمدينة وأي حد من الجنود إللي موجودين مع خالد عايز يكمل مع علي رضي الله عنه  يخليه معاه، \nوإللي عايز يرجع مع خالد للمدينة يرجع\nلما وصل علي رضي الله عنه لليمن؛ رسول الله ﷺ كان أمره إنه يُقسّم الغنائم إللي جمعها خالد،\nأربعة أخماس للجيش والخمس هيرجع بيه لرسول الله ﷺ ويتقابلوا في الحج،\nواحنا قلنا إن علي رضي الله عنه رجع من اليمن وتقابل مع رسول الله ﷺ وكان معاه سبعة وثلاثين بعير أعطاهم لرسول الله ﷺ وأكمل الهدي بتاعه للمائة\nفعلي رضي الله عنه لما كان في اليمن كان معاه خُمس الغنائم إللي هيرجعها لرسول الله ﷺ عشان يتصرف فيها،\nوالخُمس الواحد ده يُقسّم إلى خمسة أخماس:\n خمس لله والرسول ، وخمس لذوي قرابة رسول الله ﷺ، وخمس لليتامى، وخمس للمساكين، وخُمس لابن السبيل، \nزي ما ربنا قال:\n\"وَاعْلَمُوا أَنَّمَا غَنِمْتُم مِّن شَيْءٍ فَأَنَّ لِلَّهِ خُمُسَهُ وَلِلرَّسُولِ وَلِذِي الْقُرْبَىٰ وَالْيَتَامَىٰ وَالْمَسَاكِينِ وَابْنِ السَّبِيلِ\"\nكان في بقى من ضمن غنائم الخُمس ده جارية، أَمَة يعني،\nفأخذها علي رضي الله عنه لنفسه ودخل عليها، جامعها يعني، \nفلما خرج واغتسل اعترض عليه بعض الصحابة،\nإزاي يأخذ لنفسه من الخُمس إللي المفروض يرجّعه لرسول الله ﷺ؟!\nمع إن علي رضي الله عنه أخذها من الخُمس المخصص لذي القربى، وهو سيد ذي القربى، فهو ابن عم رسول الله ﷺ وكمان زوج ابنته،\nلكن حصل الاعتراض والضيق\nوكان من إللي اعترضوا صحابي اسمه بُرَيْدَة بن الحَصِيب الأَسْلَمِي،\nرجع بُرَيْدَة قبل علي رضي الله عنه وتقابل مع رسول الله ﷺ وحكى له إللي حصل،\nفمردش عليه رسول الله ﷺ ولا قال له أي حاجة\nفبُرَيْدَة رجع تاني وحكى له إللي حصل، فمردش عليه رسول الله ﷺ تاني،\nفكلمه بُرَيْدَة للمرة الثالثة، فهنا رسول الله ﷺ قال لبُرَيْدَة:\n\" يا بُرَيْدَةُ أتُبْغِضُ عَلِيًّا؟\"\nيعني انت بتكره علي؟\nفقال بُرَيْدَة: نعم.\nهو قال كده لأنه ظن إن علي رضي الله عنه أخذ حاجة مش من حقه، فاتضايق منه،\nفهنا قال رسول الله ﷺ:\n\"لا تُبْغِضْهُ فإنَّ له في الخُمُسِ أكْثَرَ مِن ذلكَ\"\nيعني متضايقش منه ولا تكرهه، ده هو له في الخمس أكثر من الجارية إللي أخذها،\nففهم بريدة وزال الإشكال إللي كان عنده، وكان بيقول بعد كده:\n\"فمَا كان مِن النَّاسِ أحدٌ أَحَبَّ إليَّ مِن عَلِيٍّ\"\nده كده كان الموقف الأول، موقف تاني حصل في طريق الرجوع من اليمن\nعلي رضي الله عنه تأخر عن القافلة إللي كانوا خارجين معاه للحج،\nفجعل عليهم قائد وقال له محدش يركب على البعير بتاع الهَدْي ولا حد يلبس ثياب معينة من الغنائم،\nفانطلقت القافلة وهو حصّلهم بعد كده، \nفلما حصلهم بعدين لقاهم ركبوا البعير إللي نهاهم يركبوه، ولبسوا الثياب إللي نهاهم يلبسوها،\nفغضب علي ونَهَرهم رضي الله عنه إزاي لا تطيعوا أمري؟\n قلت لكم لا تركبوا، أنا قلت لكم لا تلبسوا، كيف تفعلون كذا؟! فتضايقوا من معاملة علي رضي الله عنه،\nفلما تقابلوا مع رسول الله ﷺ اشتكوا له من علي إنه كان قاسي معاهم وفعل وفعل،\nفقال لهم رسول الله ﷺ:\n\"إني علمتُ أنّ علي قد أحسن فلا تبغضُوا علي\"\nيعني كأنه بيقول لهم تستاهلوا إللي علي عمله فيكم، انتم مسمعتوش الكلام\nفمحدش يزعل من علي، فسكت الناس.\nفكده احنا عندنا شكوى داخلية من علي رضي الله عنه مع إنه لم يخطئ\nفانتظر رسول الله ﷺ الوقت المناسب بعد انتهاء الحج عشان يبين مكانة علي رضي الله عنه ويوصي الصحابة بأهل بيته ﷺ\nلأنه ﷺ مكنش عايز يشغل عامة المسلمين بأمر داخلي، فبعد ما عدت نص المسافة تقريبا كان هو ده الوقت المناسب للكلام، \nيعني أهل مكة قعدوا في مكة، وإللي من الطائف رجعوا للطائف وهكذا، ولم يبقَ غير بس الصحابة إللي عايشين مع رسول الله ﷺ في المدبنة،\nفالموجودين دلوقتي هم أهل المدينة وإللي حواليها\nفهنا وصى رسول الله ﷺ الصحابة بعلي رضي الله عنه وبأهل بيته.\nودي كده كانت قصة غَدِير خم باختصار\nإن شاء الله المرة الجاية  هنشوف الأحداث إللي حصلت بعد ما رسول الله ﷺ رجع للمدينة\nمصادر جزء النهاردة في التعليقات"}, {"n": 256, "l": "الجزء 230 | احداث السنه العاشره من الهجرة | الأسود العنسي", "u": "https://www.facebook.com/groups/710210019782034/permalink/837765610359807/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائتين_وثلاثين\n#أحداث_السنة_العاشرة_من_الهجرة\n#الأسود_العنسي\nاتكلمنا المرة إللي فاتت عن الأحداث إللي حصلت بعد حجة الوداع في طريق العودة من مكة للمدينة،\nمن الأحداث إللي حصلت بعد حجة الوداع نزول آخر سورة في القرآن وهي سورة النصر،\nالعلماء اختلفوا في وقت نزولها، في إللي قالوا إنها نزلت بعد حجة الوداع، وفي إللي قالوا إنها نزلت قبل آية:\n\"اليوم أكملت لكم دينكم وأتممت عليكم نعمتي\"  مباشرة،\nوفي إللي قال إنها نزلت في وسط أيام التشريق لما كان رسول الله ﷺ في مِنَى،\nوفي إللي قال إنها نزلت قبل كده خالص أيام خيبر \nفاحنا هناخد بالقول إنها نزلت بعد حجة الوداع؛ لأنه أقرب لواقع رسول الله ﷺ حاليا\n☆إزاي يعني\nخلونا نشوف الآيات ونشوف تفسيرها،\nربنا بيقول:\n\" إِذَا جَاءَ نَصْرُ اللَّهِ وَالْفَتْحُ ۩ \nوَرَأَيْتَ النَّاسَ يَدْخُلُونَ فِي دِينِ اللَّهِ أَفْوَاجًا ۩ فَسَبِّحْ بِحَمْدِ رَبِّكَ وَاسْتَغْفِرْهُ إِنَّهُ كَانَ تَوَّابًا\"\nالمعنى الإجمالي للآيات هو إن يا محمد إذا شوفت إن ربك خلاص أعانك على عدوك وقوّاك، وأيّدك، فانتصرت عليهم\nوتم خلاص فتح مكة،\nوالناس دخلت في دين الإسلام جماعات؛ يبقى انت مهمتك خلاص انتهت، وهنا هتسبح بحمد ربك وتستغفره عشان تستعد للقاء الله\n◇طيب سؤال، اشمعنى يعني فتح مكة بالذات إللي ربنا ذكره في الآية\nده لأن أحياء العرب كانوا مستنيين إللي هيحصل بين رسول الله ﷺ وبين قريش،\nيعني كانوا بيقولوا لو محمد ظهر وانتصر على قريش فهو كده خلاص نبي وساعتها هنتبعه،\nلكن لو قريش هي إللي غلبته يبقى هو مكنش نبي وأدينا مع قريش زي ما احنا\nفبعد ما رسول الله ﷺ انتصر على قريش وتم فتح مكة بقت الأمور واضحة للكل إن رسول الله ﷺ نبي وبدأوا يدخلوا في دين الله أفواجا زي ما شوفنا كده في عام الوفود.\n◇سؤال تاني،\n ليه ربنا أمر رسول الله ﷺ بالاستغفار\nلأن المشروع في ختام الأعمال هو الاستغفار والتسبيح،\nيعني مش بعد ما نخلص صلاة مش أول حاجة بنقولها من أذكار الصلاة: استغفر الله ثلاث مرات\nوكذلك بعد الانتهاء من الحج ربنا أمر إن العبد يُكثر من ذكر الله، قال تعالى:\n\"فَإِذَا قَضَيْتُمْ مَنَاسِكَكُمْ فَاذْكُرُوا اللَّهَ كَذِكْرِكُمْ آبَاءَكُمْ أَوْ أَشَدَّ ذِكْرًا\"\nوكذلك المجالس تُختم بالاستغفار، يعني لما يكون ناس قاعدين مع بعض في مجلس وبعد ما خلاص يخلصوا قاعدتهم يقولوا:\n\" سبحانك اللهم وبحمدك، أشهد أن لا إله إلا أنت، أستغفرك وأتوب إليك\" وهكذا،\nفكده خلاص اكتملت الرسالة، وأجل رسول الله ﷺ اقترب، فبقى المشروع هنا الاستغفار وذكر الله،\nفالمقصود إن السورة نَعَت إلى رسول الله ﷺ أجله، يعني يا محمد! استغفر؛ لأنك ستموت\nوالسيدة عائشة قالت إن بعد نزول السورة دي كان رسول الله ﷺ يُكثر في الركوع والسجود من قَول:\n\"سبحانك اللهم ربنا وبحمدك، اللهم اغفر لي\"\n¤وطبعا هنا لازم نقف وقفة\nرسول الله ﷺ إللي هو سيد ولد آدم وهو الأفضل والأَوْرَع، ربنا أمره بالاستغفار، فما بالكم بغيره إللي هو احنا،\nيعني هنا كأن ربنا بيقولنا:\nإذا كان أفضلكم أُمِر أن يَستغفر، فأنتم أيها المذنبون الأكثر ذنوباً من باب أَوْلى أن تستغفروا.\nوده الفرق بين المؤمن والفاجر، رسول الله ﷺ بيقول:\n\"إن المؤمنَ يرى ذنوبَه كأنه قاعدٌ تحت جبلٍ يخاف أن يقعَ عليه\"\nيعني المؤمن شايف ذنوبه الصغيرة كأنها جبل وهو قاعد تحته وخايف أحسن يقع عليه ويهلكه،\nأما الفاجر المُنحرف عن شرع الله والمُستهين بتعاليم الدين قال عنه رسول الله ﷺ:\n\" وإن الفاجرَ يرى ذنوبَه كذُبابٍ مرَّ على أنفِه، فقال به هكذا\"\nيعني الفاجر ده شايف ذنوبه كأنها ذبابة جت وقفت على أنفه فهشها بإيده وطارت وخلاص وكأنها مكنتش موجودة\nفالفاجر مش بيفرق معاه وقوعه في المعاصي ومُستهين بيها، أما المؤمن فبيشوف الذنب البسيط شيء عظيم جدا ويفضل خايف وقلقان منه ويفضل يستغفر ويتوب ويعمل الأعمال الصالحة عشان ربنا يكفّر عنه سيئاته\nفزي مانتم شوفتم كل حاجة استقرت بعد حجة الوداع، فكان أقرب للواقع نزول سورة النصر بعد حجة الوداع،\nطبعا الموضوع على خلاف بين العلماء زي ما قلنا\nلكن أنا قلت لكم الرأي إللي أنا بميل له،  \nولو عايزين تعرفوا تفصيل باقي الآراء التانية هتلاقوا الرابط في التعليقات\n من كتاب:\n《التحرير والتنوير لابن عاشور》\nرجع رسول الله ﷺ للمدينة، وأول ما شافها كبّر ثلاث مرات وقال:\n\" لا إلَهَ إلَّا اللَّهُ، وحْدَهُ لا شَرِيكَ له، له المُلْكُ، وله الحَمْدُ، وهو علَى كُلِّ شيءٍ قَدِيرٌ. \nآيِبُونَ تَائِبُونَ، عَابِدُونَ سَاجِدُونَ، لِرَبِّنَا حَامِدُونَ صَدَقَ اللَّهُ وعْدَهُ، ونَصَرَ عَبْدَهُ، وهَزَمَ الأحْزَابَ وحْدَهُ\"\nودخل رسول الله ﷺ المدينة، وبكده بدأ العد التنازلي في حياة رسول الله ﷺ \nخِلص شهر ذي الحجة ودخلنا في شهر محرم من السنة الحادية عشرة للهجرة،\nفي الشهر ده ظهر الأسْود العَنْسِيُّ مُدّعي النبوة، وقيل ظهر في أواخر شهر ذي الحجة،\nالمهم هو ظهر زي ما رسول الله ﷺ تنبأ وفسّر الرؤيا بتاعة السُّوارِين إللي كانوا من ذهب واتكلمنا عنهم لما اتكلمنا عن مسيلمة الكذاب في الجزء مائتين وسبعة عشر لو تفتكروا\n☆إيه بقى قصة الأسود العنسي ده\nالأسود العنسي كان رجل ضخم الجسم وقوي وشجاع وكان بيستخدم الكهانة والسحر، وكان خطيب بليغ،\nيعني بيتكلم كلام يقدر يضحك بيه على إللي بيكلمه\nوكان يُرِي قومه الأعاجيب من خلال بقى السحر والاستعانة بالجن، واستخدم الأموال للتأثير على الناس\nوهو من قبيلة مَذْحَج في جنوب اليمن، \nفتقدروا تقولوا كده إنه شاف نفسه وشاف قدراته فراح قايل للناس إنه نبي، وفي نفس الوقت لم يُنكر نبوة رسول الله ﷺ، \nوراح مسمي نفسه رحمان اليمن\nخدوا بالكم إن مسيلمة الكذاب لسه عايش، فبقى عندنا دلوقتي رحمان اليمامة ورحمان اليمن \nكان الأسود العنسي بيدّعي إن في ملكين يأتيانه بالوحي وهما: سَحيق وشقيق أو شَرِيق،\nوناس كتير أيدته واتبعوه ومنهم بنو الحارث بن كعب إللي كانوا أسلموا قبل كده لكنهم ارتدوا دلوقتي لأنهم أصلا كانوا داخلين الإسلام وهم كارهينه،\nخلال الثلاث شهور إللي ظهر فيهم دول انتشر أمره وكوّن جيش وقتل شِهر بن باذان حاكم صنعاء إللي كان أسلم مع أبوه باذان وأقره رسول الله ﷺ على حكم اليمن بعد موت أبيه باذان.\n☆فاكرين باذان الفارسي إللي كان كسرى أرسله رسالة بيقول له فيها إنه يأتيه برسول الله ﷺ فكان رد رسول الله ﷺ إن ربنا قتل كسرى وأسلم بعدها\nأهه باذان ده مات وابنه مسك حكم اليمن بعده، وجاء الاسود العنسي وقتله،\nوده كان من أسباب انتشار أمر الأسود واتباع أهل اليمن له؛\nلأن هو يمني وبكده خلصهم من الفارسي إللي كان حاكمهم من زمن، وأهل اليمن أصلا من زمان عايزين يتخلصوا من حكم فارس، فدي فرصة بالنسبة لهم،\nوطبعا حصلت معارك بين الأسود العنسي وأتباعه وبين المسلمين، \nفتغلب عليهم الأسود العنسي وهرب المسلمون من صنعاء وكان منهم معاذ بن جبل رضي الله عنه إللي رسول الله ﷺ كان أرسله عشان يعلم أهل اليمن زي ما قلنا قبل كده،\nوكان الأسود العنسي له مواقف بشعة في تعذيب المسلمين المتمسكين بالإسلام\nعشان كده تعامل معه المسلمون إللي كانوا في المناطق إللي تحت إدارته بالتُّقيَة،\nيعني يظهروا إنهم مش مسلمين لكنهم من داخلهم مؤمنين بالله وبرسوله ﷺ،\nوبسبب الانتصارات إللي كانت ورا بعض سيطر على منطقة واسعة وبقى ملكه كبير يصل إلى حدود الطائف،\nلكن مع كل ده المسلمين تجمعوا وحاولوا يتصدوا للأسود العنسي وكتبوا لرسول الله ﷺ رسالة يخبروه باللي حصل،\nطبعا وصلت الأخبار دي لرسول الله ﷺ وهو كان مريض مرض الموت وهنعرف إيه موضوع المرض ده بالتفصيل لما ييجي وقت الكلام عنه،\nلكن دلوقتي هنخلينا في أحداث اليمن، طبعا موقف صعب على رسول الله ﷺ وهو مريض،\nيعني هو بيشوف جهوده في نشر الإسلام في اليمن وتوحيد قبائله تتعرض للنكسة بسبب واحد زي الأسود العنسي ده\nوعلى الرغم من الوجع إللي كان فيه رسول الله ﷺ فده لم يشغله عن أمر الله تعالى والدفاع عن دينه\nأرسل رسول الله ﷺ الرّسل إلى اليمن يأمر اليمنيين بالقضاء على الأسود العنسي، ويستنهضهم للمواجهة الذاتية معه،\nيعني رسول الله ﷺ لم يُرسل جيش من المدينة للقضاء عليه، \nولكنه اعتمد على قوى أهل اليمن نفسهم، وأرسل رسائل لزعماء المناطق المحيطة في منطقة اليمن عشان يساعدوا في القضاء على فتنة الأسود العنسي،\nلكن مع كل المحاولات والمجهودات دي محدش استطاع إنه يقضي على الفتنة دي\n☆إزاي طيب مات الأسود العنسي\nأجمعت قوى المسلمين المتجمعة على قتل الأسود العنسي، فعملوا خطة، ضموا لهم زوجة الأسود وهي كانت زوجة شِهر بن باذان الحاكم المقتول وكانت امرأة تقية ذات دين تزوجها الأسود بالغصب،\nواتفقوا مع قائد جنود الأسود العنسي على قتله، وكان قائد الجنود ده على خلاف مع الأسود،\nالمهم هم دبروا خطة لقتله،\nوالخطة كانت إن زوجته الفارسية حددت لهم ليلة، يأتي فيها مجموعة من المقاتلين عشان يقتلوه،\nوحددت لهم باب محدش من الحراس بيقف يحرس عنده فهيبقى سهل يدخلوا منه،\nفتسلل إلى قصر الأسود العنسي في الليلة المُتفق عليها أربعة من قادة المسلمين وكان من ضمنهم ابن عم المرأة الفارسية،\nفدخل القادة على الأسود بعد ماكانت زوجته الفارسية سقته خمر لحد ما بقى سكران سُكر شديد،\nوهم بيقتلوه صرخ صرخة شديدة جاء الحرس بسببها، فخرجت لهم زوجته وقالت لهم:\n\" إن النبي يُوحى إليه\"\nفسكنوا وهدأوا ورجعوا لمكانهم، وقطع رأس الأسود واحد من القادة الأربعة وفي الصباح طلع على سور المدينة وهو ماسك رأس الأسود العنسي وقال:\n\"اللَّه أكبر اللَّه أكبر أشهد أن لا إلا اللَّه وأشهد أن محمدا رَسُول اللَّهِ وأن الأسود كذاب عدو اللَّه\"\nفاجتمع أصحاب الأسود، فألقى إليهم رأسه في ساحة القصر،\nفاتفزعوا وخافوا وطلعوا يجروا من الخوف فهجم عليهم المسلمون ولم ينجوا منهم إلا من أسلم،\nوالناس قعدوا ينادوا على بعض في المدينة فخرجوا صباحًا، واضطرب الوضع وبعدين استقرت الأمور على أن يتولى الأمر معاذ بن جبل رضي الله عنه\nامتى بقى كانت النهاية دي\nكانت قبل وفاة رسول الله ﷺ بيوم أو ليلة، جاءه الوحي فبشره بهلاك الأسود العنسي وأخبر رسول الله ﷺ الصحابة بالخبر ده،\nوبعدين بقى جاء الخبر من اليمن بعد ما بُويع لأبي بكر رضي الله عنه بالخلافة بعد موت رسول الله ﷺ.\nهنرجع بقى للمدينة ونشوف أهم الأحداث إللي حصلت في آخر حياة رسول الله ﷺ في السنة الحادية عشرة للهجرة من أول الحلقة الجاية إن شاء الله\nمصادر جزء النهاردة في التعليقات"}, {"n": 257, "l": "الجزء 231 | بعث أسامه ومرض رسول الله", "u": "https://www.facebook.com/groups/710210019782034/permalink/837765777026457/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائتين_وواحد_وثلاثين\n#أحداث_السنة_الحادية_عشرة_من_الهجرة\n#بَعْث_أسامة_ومرض_رسول_الله\nهنبدأ النهاردة الكلام عن أحداث السنة الحادية عشرة من الهجرة في عهد رسول الله ﷺ، \nاستمرت الحياة في المدينة عادي جدا، رسول الله ﷺ يصلي الصلوات مع الصحابة، واستمرت نزول آخر آيات القرآن،\nوكانت الأوضاع في المدينة مستقرة،\nوعرفنا إن رسول الله ﷺ كان عارف من خلال الأحداث إن أجله خلاص قرب،\nفكان رسول الله ﷺ بيفكر فيما بعد موته، فجهز جيش بقيادة أسامة بن زيد بن حارثة وأمره إنه يتوجه إلى الشام لقتال الروم،\nوالكلام ده كان في شهر صفر من السنة الحادية عشرة من الهجرة.\n☆طيب ليه رسول الله ﷺ جهّز الجيش ده لقتال الروم في الوقت ده\nالعلماء بيقولوا إنه بسبب إن الرومان قتلوا واحد اسمه فَرْوَة بن عمرو الجُذامي، وهو كان والياً على مدينة مَعَان في الشام من قِبَلِ الروم،\nفلما أسلم؛ الرومان قتلوه حقدا وغيظا، يعني إزاي واحد هم معينينه يروح يتبع الدين الجديد ده\nفلما وصل الخبر لرسول الله ﷺ كان لازم يكون في رد حاسم على إللي عملوه ده،\nوخصوصا إن دولة الإسلام دلوقتي دولة قوية، يعني تقدر ترد على أي حد يعتدي عليها،\nواحنا عارفين إن الاعتداء على فرد واحد من المسلمين ساعتها كان يُعتبر اعتداء على دولة الإسلام كلها،\nفرسول الله ﷺ جهز جيش لقتال الروم\nوطبعا هنا لينا وقفة مع القائد إللي رسول الله ﷺ عينه عشان يقود المعركة المهمة دي\nقائد الجيش هو أسامة بن زيد بن حارثة رضي الله عنه، وساعتها كان عمره سبعة عشرة سنة، يعني في ثانوية عامة عندنا\nلأ، وإيه الجيش ده كان فيه كل كبار الصحابة، أبو بكر وعمر وعثمان وسعد بن أبي وقاص وغيرهم، \nفالمنافقين بدأوا يتكلموا عشان يوقعوا بين المسلمين، قعدوا يقولوا إزاي رسول الله ﷺ يجعل شاب لم يبلغ مبلع الرجال قائد لجيش فيه كبار الرجال؟!!\nفانتشر القيل والقال في موضوع أسامة و تأميره وتوليته أمر قيادة الجيش الإسلامي وإن رسول الله ﷺ خلاه هو القائد قال عشان بيحبه\n☆طيب إيه وجهة نظر رسول الله ﷺ في إنه يجعل شاب صغير زي أسامة هو إللي يقود جيش مهم زي ده\nرسول الله ﷺ بيعرّفنا وبيعلمنا إن مش مهم مين يكون هو القائد، ولا نسبه إيه، ولا حتى عمره كم،\nالمهم هو كفاءة القائد، وإنه بيحتكم في كل أموره إلى كتاب الله عز وجل، وإلى سنة نبيه ﷺ، وبيعلمنا نستغل طاقات الشباب الهائلة،\nيعني مش عشان ده شاب وسنه صغير يبقى نلغيه من حسابتنا حتى لو كان عنده الكفاءة لمجرد إنه صغير في السن\nالمهم، الكلام انتشر بين الناس ووصل لرسول الله ﷺ وساعتها كان رسول الله ﷺ كان مريض فخرج للناس وهو رابط رأسه من شدة الصداع، فخطب فيهم وقال:\n\"قدْ بَلَغَنِي أنَّكُمْ قُلتُمْ في أُسَامَةَ وإنَّه أحَبُّ النَّاسِ إلَيَّ،\nأنْ تَطْعُنُوا في إمارَتِهِ، فقَدْ كُنْتُمْ تَطْعُنُونَ في إمارَةِ أبِيهِ مِن قَبْلُ،\nوايْمُ اللَّهِ إنْ كانَ لَخَلِيقًا لِلْإِمارَةِ، وإنْ كانَ لَمِنْ أحَبِّ النَّاسِ إلَيَّ، وإنَّ هذا لَمِنْ أحَبِّ النَّاسِ إلَيَّ بَعْدَهُ،\nأَنْفِذُوا بَعَثَ أُسَامَةَ\"\nيعني رسول الله ﷺ بيقولهم إنه وصل له كلام إنهم بيطعنوا في أسامة وإنه لايستحق الإمارة وأنه بقى القائد عشان رسول الله ﷺ بيحبه،\nزي ما كانوا اتكلموا قبل كده في زيد بن حارثة رضي الله عنه لما رسول الله ﷺ خلّاه قائد على على سرية مؤتة وهو كان مَوْلى،\nفأقسم لهم بالله إن أسامة يستحق الإمارة وجدير بها زي بالضبط ما كان أبوه زيد مُستحق للقيادة\n¤ماهو بالعقل كده يا جماعة رسول الله ﷺ مش هيضيّع جيشه، ولا يُخاطر بمصير أمته عشان واحد بيحبه بس وميكونش هو نفسه كُفء ويستحق القيادة دي\nوخصوصا إن القتال هيكون مع أقوى قوة في الأرض في زمانهم، \nورسول الله ﷺ لو مكنش موقن تمام اليقين إن أسامة بن زيد رضي الله عنهما أهل للمهمة دي مكنش ولّاه، \nوخصوصا إن كان تحت قيادة أسامة مجموعة فذة من القادة العسكريين، ومن السابقين للإسلام وكفاية إن كان من جنود أسامة رضي الله عنه واحد زي عمر بن الخطاب\nوبرده رسول الله ﷺ لم يُنكر حبه لأسامة ولا حبه لأبيه زيد وإنهم من أحب الناس له، لكن مش ده المقياس للقيادة،\nالمقياس هو الكفاءة، هل يقدر على الأمر ده ولّا لأ\nفي الأول كان في تباطُؤ في الالتحاق بجيش أسامة، لكن بعد كلام رسول الله ﷺ الناس بدأت تتجمع وتجهزت وخرج الجيش من المدينة وخيم في منطفة اسمها 《الجُرْف》 على بُعد خمسة كيلو مترات ونصف من المدينة،\nلكن الجيش لم يخرج للشام بسبب الأخبار المُقلِقة عن اشتداد مرض رسول الله ﷺ، \nفكانوا مستنيين يطمنوا على رسول الله ﷺ قبل ما يخرجوا للمعركة وخصوصا إن دي أول مرة يمرض فيها رسول الله ﷺ المرض الشديد ده\n☆إيه موضوع مرض رسول الله ﷺ \nفي آخر شهر صفر خرج رسول الله ﷺ وتوجّه إلى البَقِيع، فصلى صلاة الجنازة على شهداء أحد ودعا لهم،\nوبعدها توجه للمنبر فخطب في الناس وقال:\nإنِّي فَرَطُكُمْ، وأَنَا شَهِيدٌ علَيْكُم، وإنِّي واللَّهِ لَأَنْظُرُ إلى حَوْضِي الآنَ،\nوإنِّي قدْ أُعْطِيتُ مَفَاتِيحَ خَزَائِنِ  الأرْضِ - أوْ مَفَاتِيحَ الأرْضِ - وإنِّي واللَّهِ ما أخَافُ علَيْكُم أنْ تُشْرِكُوا بَعْدِي، ولَكِنِّي أخَافُ علَيْكُم أنْ تَنَافَسُوا فِيهَا\"\nفَرَطُكُمْ معناها سَابِقُكُم، يعني هو بيقول للصحابة إنه ﷺ هيسبقهم على الحوض وهيكون أول واحد يوصل ويقف عند الحوض يوم القيامة،\nوهو شاهد عليهم وبيحذرهم من إنهم يعملوا أي عمل يكون سبب في إن الملائكة تبعدهم عن حوضه، \nوكلمة: 《إنِّي أُعْطِيتُ مَفَاتِيحَ خَزَائِنِ الأرضِ》\nده إشارة إلى اتساع الدولة الإسلامية وكثرة الفتوحات وطبعا ده هيؤدي إلى كثرة الأموال في أيدي المسلمين بسبب الغنائم إللي هيحصلوا عليها،\nفهنا عبّر رسول الله ﷺ عن خوفه عليهم من إن كثرة الأموال ممكن تخليهم يتافسوا فيما بينهم فيؤدي التنافس ده إلى العداوة والبغضاء والتقاتل على الدنيا وخيراتها\nبعد الخطبة دخل رسول الله ﷺ دخل بيت عائشة رضي الله عنها وهو عنده صداع شديد فلقاها هي كمان بتشتكي من الصداع وبتقول: وارَأْسَاه!\nيعني زي ما بنقول كده: أه يا راسي\nفقال لها رسول الله ﷺ:\nبل أنا يا عائشةُ وارَأْسَاه.\nيعني أنا إللي فعلا راسي بتوجعني، وكان من عادة رسول الله ﷺ إنه يداعب السيدة عائشة لما تكون مريضة فقال لها وهو يداعبها في الكلام:\n\"وما ضرَّكِ لو مِتِّ قبْلي فغسَلْتُكِ وكفَّنْتُكِ وصلَّيْتُ عليكِ ثمَّ دفَنْتُكِ\"\nيعني متقلقيش، لو مُتّي قبلي هغسلك وأكفنك وهصلي عليكِ وأدفنك، فالسيدة عائشة قالت له:\n\"وا ثُكْلِيَاهْ،\n واللَّهِ إنِّي لَأَظُنُّكَ تُحِبُّ مَوْتِي، ولو كانَ ذَاكَ، لَظَلِلْتَ آخِرَ يَومِكَ مُعَرِّسًا ببَعْضِ أزْوَاجِكَ\"\nيعني كأنها بتقول بلغتنا دلوقتي:\nيا نهار أبيض\nوالله انت شكلك كده عايزني أموت، ولو حصل ومُت هترجع بعد ما تدفني تروح تقعد مع بعض أزواجك عادي ولا هتتأثر بموتي وهتنساني\nفتبسم رسول الله ﷺ من كلام السيدة عائشة \nوبعدين قال للسيدة عائشة:\n\"لقَدْ هَمَمْتُ - أوْ أرَدْتُ - أنْ أُرْسِلَ إلى أبِي بَكْرٍ وابْنِهِ وأَعْهَدَ: أنْ يَقُولَ القَائِلُونَ - أوْ يَتَمَنَّى المُتَمَنُّونَ\"\nيعني رسول الله ﷺ بيقول إنه كان عايز يُرسل لأبي بكر الصديق رضي الله عنه ويوصي له بالخلافة عشان مفيش واحد يطلع ويقول أنا أحق بالخلافة، أو عشان محدش يتمنى الخلافة،\nفرسول الله ﷺ كان عايز يعمل كده عشان ينهي أي نزاع أو خلاف يحصل بعد موته ﷺ،\nلكنه توقف لأن الله أراد إن المسلمين ياخدوا أجر اجتهادهم ويكون القرار نابع منهم هم\nبعد الحوار ده اشتد الوجع برسول الله ﷺ، وكان مرضه صداع وحُمّى شديدة، سخونية يعني،\nوكان بيطوف على نسائه بالرغم من شدة وجعه وكان بيسأل كل يوم:\nأين أنا غداً؟ أين أنا غداً؟\nفكانت كل واحدة من زوجاته تقول له عند فلانة، لحد ما وصل بيت ميمونة رضي الله عنها واشتد به الوجع، فسأل:\nأين أنا غداً؟\nفقالوا له عند عائشة فسَكَن رسول الله ﷺ واستأذن نساءه إنه يُطَبّب في بيت عائشة، فأذنت له زوجاته،\nرسول الله ﷺ وصل بيه شدة الوجع إنه مش قادر يمشي، \nفخرج رسول الله ﷺ من بيت ميمونة وهو متسنّد على رجلين، عمه العباس وعلي بن أبي طالب،\nوكانت قدمه ﷺ تخُط في الأرض، يعني هو في النص وساند عليهم وماشيين بيه ورجله بتجرجر في الأرض مش قادر حتى يسند عليها وهو ماشي،\nلحد ما وصلوه لبيت عائشة، كانوا بيعملوا له كمادات عشان الحرارة تنزل، \nفكان في قماشة على رأسه ﷺ لو حد وضع إيده عليها كان يحس بالحرارة العالية من فوقها،\nوكان رسول الله ﷺ رابط راسه من شدة الصداع،\nالسيدة عائشة بتوصف وجع رسول الله ﷺ وبتقول:\n\"ما رَأَيْتُ أحَدًا أشَدَّ عليه الوَجَعُ مِن رَسولِ اللَّهِ ﷺ\"\nيعني عمرها ما شافت حد اشتد عليه المرض أكثر من رسول الله ﷺ ،\nوعبد الله بن مسعود بيقول إنه دخل على رسول الله ﷺ وهو عنده حمى شديدة فمسّه بيده، بيشوف حرارته يعني،\nفقال له ابن مسعود:\nيا رَسولَ اللَّهِ، إنَّكَ لَتُوعَكُ وعْكًا شَدِيدًا؟\nيعني انت الحمى بتاعتك بتكون شديدة؟\nفقالَ له رَسولُ اللَّهِ ﷺ:\nأجَلْ، إنِّي أُوعَكُ كما يُوعَكُ رَجُلانِ مِنكُم.\nيعني الحُمّى بتاعتي بتبقى مضاعفة، بتجيلي زي ما بتيجي لرجلين منكم،\nفقال له ابن مسعود:\nذلكَ أنَّ لكَ أجْرَيْنِ؟\nيعني انت كده لك أجر رَجُليْن يا رسول الله؟\nفقال له رسول الله ﷺ:\nأجَلْ، ثُمَّ قالَ رسول الله ﷺ:\n\"ما مِن مُسْلِمٍ يُصِيبُهُ أذًى، مَرَضٌ فَما سِواهُ، إلَّا حَطَّ اللَّهُ له سَيِّئاتِهِ، كما تَحُطُّ الشَّجَرَةُ ورَقَها\"\nيعني مفيش مسلم ربنا يبتليه بأي أذى سواء مرض أو غيره إلا أسقط الله عنه من سيئاته، زي ما ورق الشجر بيقع كده بسبب هبوب الريح\nكان زوجات رسول الله ﷺ بيزوروه في بيت عائشة، فالسيدة صفية لما شافت رسول الله ﷺ وهو مريض أوي كده قعدت تبكي وتقول له:\nأَمَا وَاللَّهِ يَا نَبِيَّ اللَّهِ لَوَدِدْتُ أَنَّ الَّذِي بِكَ بِي.\nيعني بتقول بلهجتنا كده ياريتني كنت مكانك، \nفَغَمَزْنَهَا أَزْوَاجُ النَّبِيِّ ﷺ وَأَبْصَرَهُنَّ رَسُولُ اللَّهِ ﷺ ، فَقَالَ: مَضْمِضْنَ.\nيعني زوجات رسول الله ﷺ غمزوا لبعض بعد ما سمعوا كلمة صفية، قال يعني شوفوا بتقول إيه، يقصدوا يعني إنها بتمثل\nلكن رسول الله ﷺ شافهم فقال لهم يتمضمضوا، \nفقالت زوجات رسول الله ﷺ:\nمِنْ أَيِّ شَيْءٍ يَا نَبِيَّ اللَّهِ ؟ \nيعني نتمضمض من إيه، فقال رسول الله ﷺ:\nمِنْ تَغَامُزِكُنَّ بِصَاحِبَتِكُنَّ ، وَاللَّهِ إِنَّهَا لَصَادِقَةٌ\nيعني رسول الله ﷺ هنا شهد للسيدة صفية بالصدق وإنها فعلا تتمنى إن رسول الله ﷺ يكون سليم مُعافى وتكون هي مريضة بداله، \nوبيّن خطأ زوجاته إللي كان طبعا بسبب الغيرة\nوده من ضمن المواقف إللي تعامل فيها رسول الله ﷺ مع أخطاء زوجاته بسبب غيرتهن، مع إنه كان مريض مرض شديد زي ما شفنا\nهنكمل المرة الجاية إن شاء الله باقي الأحداث في آخر أيام رسول الله ﷺ في الدنيا\nمصادر جزء النهاردة في التعليقات"}]);
